  ui_story_5024_50240201_50_dialog_content = "ได้ ๆ",
  ui_story_5024_50240201_51_dialog_content = "เดี๋ยวก่อน คาร์ลีน!",
  ui_story_5024_50240201_52_dialog_content = "หืม? มีอะไรเหรอ?",
