  ui_story_5024_50240201_56_dialog_content = "ใครเอาของแบบนี้มาตั้งบนถนนนะ?",
  ui_story_5024_50240201_57_dialog_content = "เราเดินผ่านถนนเส้นนี้ตั้งหลายครั้ง ทำไมเพิ่งมาเห็นเอาตอนนี้ล่ะ?",
  ui_story_5024_50240201_58_dialog_content = "เราไปกันเถอะ... ฉันรู้สึกไม่ดีเลย...",
  ui_story_5024_50240201_59_dialog_content = "<color=#e8d9bb>ตุบ ตุบ ตุบ</color>",
  ui_story_5024_50240201_60_dialog_content = "(ที่นี่มันแปลก ๆ ชอบกล)",
  ui_story_5024_50240201_61_dialog_content = "(หรือจะมีสิ่งที่ตามองไม่เห็นซ่อนอยู่?)",
