  ui_story_5024_50240201_67_dialog_content = "แต่พอคิดว่าเกรเทลต้องอยู่ที่นี่ตัวคนเดียว ฉันก็ไม่สบายใจเลย",
  ui_story_5024_50240201_68_dialog_content = "เกรเทลกับคนเพี้ยน ๆ เมื่อกี้... กำลังตามหาสิ่งเดียวกันสินะ?",
  ui_story_5024_50240201_69_dialog_content = "ละครหนึ่งเดียวในโลกที่โรงละครแดนมหัศจรรย์...",
  ui_story_5024_50240201_70_dialog_content = "เธอบอกว่าเห็นชื่อโรงละครจากในบันทึก แล้วมีข้อมูลอะไรมากกว่านี้รึเปล่า?",
  ui_story_5024_50240201_71_dialog_content = "เกรเทลจดชื่อโรงละครไว้หลายแห่ง ฉันก็แค่มองผ่าน ๆ น่ะ",
  ui_story_5024_50240201_72_dialog_content = "ที่ฉันจำชื่อได้ก็เพราะที่นั่นเคยเกิดอุบัติเหตุ เลยปิดกิจการไปหลายปีแล้ว",
  ui_story_5024_50240201_73_dialog_content = "ปิดกิจการงั้นเหรอ?",
  ui_story_5024_50240201_74_dialog_content = "ฉันคิดว่ามันคงไม่เกี่ยวกับเรื่องที่เรากำลังสืบอยู่ ก็เลยไม่ได้อ่านต่อ",
