  ui_story_5024_50240201_83_dialog_content = "<color=#e8d9bb>ตุบ ตุบ ตุบ</color>",
  ui_story_5024_50240201_84_dialog_content = "ฉันได้ยินเสียงฝีเท้า!",
  ui_story_5024_50240201_85_dialog_content = "นี่มัน...",
  ui_story_5024_50240201_86_dialog_content = "อิคลิพไซท์? ในเขตบ้านเรือนประชาชนของลูโมโพลิสเนี่ยนะ?",
  ui_story_5024_50240201_87_dialog_content = "<anim type=Shake><size=45>กรรรร!!</size></anim>",
  ui_story_5024_50240201_88_dialog_content = "คาร์ลีน ระวัง!",
  ui_story_5024_50240202_1_dialog_content = "อิคลิพไซท์? ที่นี่เนี่ยนะ? เป็นไปไม่ได้...",
  ui_story_5024_50240202_2_dialog_content = "นั่นสิ... นี่มันไม่แค่ประหลาดแล้วนะ มันอันตรายสุด ๆ เลย!",
