  ui_story_5024_50240202_13_dialog_content = "เรากลับมาที่เดิมงั้นเหรอ?",
  ui_story_5024_50240202_14_dialog_content = "เป็นไปไม่ได้... เราเดินไปข้างหน้าอย่างเดียวนี่นา...",
  ui_story_5024_50240202_15_dialog_content = "...",
  ui_story_5024_50240202_16_dialog_content = "ตอนอยู่มืด ๆ เราอาจจะเลี้ยวผิดตรงไหนสักที่ก็ได้",
