  ui_story_5024_50240301_8_dialog_content = "ต้องขอโทษด้วย เลนอร์ไม่ได้ตั้งใจจะทำให้คุณกลัว",
  ui_story_5024_50240301_9_dialog_content = "ปกติเลนอร์จะไม่คุยกับคนแปลกหน้าเพราะคุณแม่ห้ามไว้",
