  ui_story_5024_50240301_13_dialog_content = "ใช่",
  ui_story_5024_50240301_14_dialog_content = "เป็นตุ๊กตาที่พูดได้เหรอ?",
  ui_story_5024_50240301_15_dialog_content = "เลนอร์ก็ไม่รู้เหมือนกันว่าตัวเองคืออะไร",
