  ui_story_5024_50240301_59_dialog_content = "\"ฉบับเดือนมีนาคม: ละครเรื่องเจ้าหมาขี้เซาจะฉายรอบปฐมทัศน์ ณ โรงละครแดนมหัศจรรย์ในอีก 6 เดือน\"",
  ui_story_5024_50240301_60_dialog_content = "\"บทละครที่น่าติดตามจากนิทานเด็กสุดอลังการ\"",
  ui_story_5024_50240301_61_dialog_content = "เจ้าหมาขี้เซา...",
  ui_story_5024_50240301_62_dialog_content = "\"ฉบับเดือนตุลาคม: เกิดอุบัติเหตุระหว่างการแสดงเรื่องเจ้าหมาขี้เซา! โรงละครแดนมหัศจรรย์ปิดกิจการ!\"",
  ui_story_5024_50240301_63_dialog_content = "ที่โรงละครปิดก็เพราะแบบนี้นี่เอง!",
  ui_story_5024_50240301_64_dialog_content = "ยังมีต่ออีกนะ",
  ui_story_5024_50240301_65_dialog_content = "\"ทีมงานทุกคนที่เกี่ยวข้องกับละครเจ้าหมาขี้เซาเสียชีวิตในอุบัติเหตุทั้งหมด เรื่องราวทั้งหมดจะเป็นปริศนาไปตลอดกาล\"",
