  ui_story_5024_50240301_67_dialog_content = "ยังไม่ทันแสดงจบก็ต้องถูกยกเลิก... ไม่แปลกเลยที่เกรเทลจะบอกว่ามันเป็นละครหนึ่งเดียวในโลก",
  ui_story_5024_50240301_68_dialog_content = "มีเขียนไว้มั้ยว่าเกิดอะไรขึ้น?",
  ui_story_5024_50240301_69_dialog_content = "หนังสือพิมพ์ไม่ได้บอกอะไรเลย หัวข้อข่าวนี้เล็กนิดเดียวเอง",
  ui_story_5024_50240301_70_dialog_content = "เลนอร์จำละครเรื่องนี้ได้",
