  ui_story_5024_50240301_72_dialog_content = "เธออยู่ที่นั่นด้วยเหรอ? โรงละครแดนมหัศจรรย์เมื่อ 17 ปีที่แล้วน่ะนะ?",
  ui_story_5024_50240301_73_dialog_content = "ใช่ค่ะ แต่ตอนนั้นเลนอร์ยังเล็ก ก็เลยจำอะไรไม่ค่อยได้",
  ui_story_5024_50240301_74_dialog_content = "จำได้แค่ว่า คุณแม่สั่งให้ไป \"ดูละครด้วยกัน\"",
