  ui_story_5024_50240301_82_dialog_content = "งั้นเหรอ...",
  ui_story_5024_50240301_83_dialog_content = "ฉันเจอรายงานเกี่ยวกับโรงละครแดนมหัศจรรย์ด้วย",
