  ui_story_5024_50240301_85_dialog_content = "มีแค่ประโยคสั้น ๆ เขียนอยู่ตรงมุมกระดาษ",
  ui_story_5024_50240301_86_dialog_content = "\"โรงละครแดนมหัศจรรย์ได้รับการบูรณะขึ้นใหม่กลายเป็นภัตตาคารวิวสวยสไตล์อัมบราตัน\"",
  ui_story_5024_50240301_87_dialog_content = "ภัตตาคารวิวสวยสไตล์อัมบราตัน? ฉันเห็นอยู่นะ!",
