  ui_story_5024_50240301_95_dialog_content = "เธอ... ตามเรามาเหรอ...?",
  ui_story_5024_50240301_96_dialog_content = "ถึงเธอจะพูดคุยเหมือนคนทั่วไป... แต่ก็ยังน่าขนลุกอยู่ดีนะ...",
  ui_story_5024_50240301_97_dialog_content = "เลนอร์ก็กำลังตามหาโรงละครแดนมหัศจรรย์เหมือนพวกคุณ",
  ui_story_5024_50240301_98_dialog_content = "เธอจะไปโรงละครนั่นทำไมเหรอ?",
