  ui_story_5024_50240301_101_dialog_content = "ตามหาแม่?",
  ui_story_5024_50240301_102_dialog_content = "ใช่ คุณแม่หายตัวไปเมื่อปีที่แล้ว",
  ui_story_5024_50240301_103_dialog_content = "เธอออกเดินทางเพื่อไปดู \"การแสดงเพียงหนึ่งเดียวในโลก\" ซึ่งเป็น \"การกลับมาของละครสุดยิ่งใหญ่\"",
  ui_story_5024_50240301_104_dialog_content = "เลนอร์เชื่อว่าละครเรื่องนั้นคือเจ้าหมาขี้เซาค่ะ",
  ui_story_5024_50240301_105_dialog_content = "มันเริ่มกลับมาเล่นอีกเมื่อปีที่แล้วเหรอเนี่ย...",
  ui_story_5024_50240301_106_dialog_content = "แล้วเธอมีจดหมายเชิญได้ยังไง?",
  ui_story_5024_50240301_107_dialog_content = "มันปรากฏตัวขึ้นมาเองค่ะ",
  ui_story_5024_50240301_108_dialog_content = "ว่าไงนะ?",
  ui_story_5024_50240301_109_dialog_content = "วันนี้ จู่ ๆ ฉันก็เจอจดหมายที่บ้าน",
  ui_story_5024_50240301_110_dialog_content = "ไม่อยากจะเชื่อเลย! เธอเชื่อจดหมายแปลก ๆ ที่ไม่รู้ที่มาได้ยังไง?",
  ui_story_5024_50240301_111_dialog_content = "แถมไม่สนใจสักนิด ว่าทำไมอยู่ ๆ มันถึงโผล่มาในบ้านตัวเอง",
  ui_story_5024_50240301_112_dialog_content = "ไม่สนใจหรอก เลนอร์ต้องตามหาแม่ และตอนนั้นแม่เคยออกไปดูละครเจ้าหมาขี้เซา แค่นี้ก็พอแล้ว",
