  ui_story_5024_50240301_114_dialog_content = "เราเองก็กำลังตามหาคนอยู่เหมือนกัน ฉันว่าเราช่วยกันได้นะ",
  ui_story_5024_50240301_115_dialog_content = "ตอนนี้เรามืดแปดด้าน ได้อะไรมาช่วยสักนิดก็ยังดี",
