  ui_story_5024_50240301_117_dialog_content = "ที่จริง นอกจากการพูดจาไร้อารมณ์แล้ว อย่างอื่นเธอก็เหมือนคนจริง ๆ ไม่มีผิด",
  ui_story_5024_50240301_118_dialog_content = "ถ้าเธอไม่โผล่ออกมาให้เราสะดุ้งแบบนั้นน่ะนะ...",
  ui_story_5024_50240301_119_dialog_content = "เลนอร์ไม่ได้ตั้งใจจะทำให้คุณตกใจ",
  ui_story_5024_50240301_120_dialog_content = "รู้แล้วล่ะ รู้แล้ว... ฉันแค่ต้องทำตัวให้ชินนั่นแหละ...",
  ui_story_5024_50240301_121_dialog_content = "ว่าแต่เราทำอะไรต่อดีล่ะ? ที่นี่ดูไม่เกี่ยวกับโรงละครเลย",
  ui_story_5024_50240301_122_dialog_content = "ในเมื่อโรงละครถูกทุบทำใหม่เป็นภัตตาคาร บางส่วนของโรงละครอาจจะยังอยู่ก็ได้มั้งนะ?",
  ui_story_5024_50240301_123_dialog_content = "อย่างเช่น... ชั้นใต้ดิน หรืออะไรประมาณนั้น?",
  ui_story_5024_50240301_124_dialog_content = "ซ่อนโรงละครส่วนนึงไว้ใต้ภัตตาคาร... ก็พอจะเป็นไปได้นะ",
  ui_story_5024_50240301_125_dialog_content = "มาลองเคาะพื้นดูมั้ย ถ้ามีทางลับ เสียงมันก็น่าจะต่างออกไป",
