  ui_story_5024_50240501_87_dialog_content = "ทั้งแกะผู้บำเพ็ญตน แมวน้อยนักอ่าน และนกฮูกหิมะผู้ทะนงตนต่างก็รักเขา",
  ui_story_5024_50240501_88_dialog_content = "พวกเขาแปรงขนไอแซค ลูบหลังด้วยความเอ็นดู แถมยังให้ขนม",
  ui_story_5024_50240501_89_dialog_content = "แต่ไอแซคไม่ชอบพวกเขา!",
  ui_story_5024_50240501_90_dialog_content = "ไอแซคชอบนิทานของฉันที่สุด และเจ้าพวกนั้นก็ใจร้อน",
  ui_story_5024_50240501_91_dialog_content = "แล้วเธอล่ะ พวกเด็กหลงทาง?",
  ui_story_5024_50240501_92_dialog_content = "อยากฟังนิทานของฉันมั้ย?",
  ui_story_5024_50240501_93_dialog_content = "ก่อนอื่นเลยนะ... นายเป็นใครน่ะ?",
  ui_story_5024_50240501_94_dialog_content = "ฉันเป็นนักเล่านิทานเด็ก เรียกฉันว่า<color=#FFB400>ไจลส์</color>ก็ได้",
  ui_story_5024_50240501_95_dialog_content = "หรือจะตั้งชื่ออื่นให้ก็ได้นะ ฉันชอบชื่อเล่นเก๋ ๆ อยู่แล้ว",
  ui_story_5024_50240501_96_dialog_content = "ในเมื่อฉันไม่ใช่ตัวละครในนิทาน ก็ไม่จำเป็นต้องมีชื่อ",
  ui_story_5024_50240501_97_dialog_content = "พูดอะไรของเขานะ...? ไม่เห็นจะเข้าใจเลย",
  ui_story_5024_50240501_98_dialog_content = "อย่างน้อยเราก็รู้ว่าเขาชื่อไจลส์ล่ะนะ...",
  ui_story_5024_50240501_99_dialog_content = "พวกนายไม่เหมือนเจ้าแกะ เจ้าแมว แล้วก็เจ้านกฮูกหิมะ",
  ui_story_5024_50240501_100_dialog_content = "ที่พวกนายมาถึงนี่ได้ ก็เพราะว่าหลงทางสินะ",
  ui_story_5024_50240501_101_dialog_content = "พวกเรา... หลงทางงั้นเหรอ?",
  ui_story_5024_50240501_102_dialog_content = "เรื่องนั้น ฉันก็ไม่รู้เหมือนกันว่ามันเกิดอะไรขึ้นกับถนนที่เรามา...",
  ui_story_5024_50240501_103_dialog_content = "แต่เราอยากไปโรงละครแดนมหัศจรรย์น่ะ เรามาถูกที่รึยัง?",
  ui_story_5024_50240501_104_dialog_content = "อะไรกัน? นายก็ด้วยงั้นเรอะ?",
  ui_story_5024_50240501_105_dialog_content = "นายอยากเข้าโรงละครแดนมหัศจรรย์เหมือนพวกนั้นเหรอ?",
  ui_story_5024_50240501_106_dialog_content = "ไม่ได้... ไม่ได้เด็ดขาด! เลิกคิดได้เลย!",
  ui_story_5024_50240501_107_dialog_content = "ลืมโรงละครนั่นไปซะ! ไปหาความสำราญกับนิทาน หรือไม่ก็อาหารในงานเลี้ยง...",
  ui_story_5024_50240501_108_dialog_content = "อะไรก็ได้ ยกเว้นโรงละครนั่น!",
  ui_story_5024_50240501_109_dialog_content = "หา? แต่...",
  ui_story_5024_50240501_110_dialog_content = "นายจะเข้าไปในนั้นไม่ได้เด็ดขาด!",
  ui_story_5024_50240501_111_dialog_content = "นายนี่เหมือนพวกนั้นไม่มีผิด... ไม่ได้รู้เรื่องอะไรเลย!",
