  ui_story_5024_50240501_114_dialog_content = "อา... ทันเวลาพอดี!",
  ui_story_5024_50240501_115_dialog_content = "ในที่สุดก็มาทันจนได้",
  ui_story_5024_50240501_116_dialog_content = "นาน ๆ ทีเธอจะไม่สายนะเนี่ย",
  ui_story_5024_50240501_117_dialog_content = "หึ เฟาสต์คงเตือนเธอก่อนล่ะสิ",
  ui_story_5024_50240501_118_dialog_content = "งานเลี้ยงจะเริ่มแล้ว จะเริ่มแล้ว...",
