  ui_story_5024_50240501_125_dialog_content = "คุณวิกตอเรียกำลังมา",
  ui_story_5024_50240501_126_dialog_content = "เรามีแขกคนใหม่มากับเราด้วย เพราะงั้นอย่าแย่งเก้าอี้กันล่ะ",
