  ui_story_5024_50240501_128_dialog_content = "นั่งลงได้แล้ว เนลส์!",
  ui_story_5024_50240501_129_dialog_content = "เดี๋ยวก่อนสิ... เหลือไม่กี่จานแล้ว...",
  ui_story_5024_50240501_130_dialog_content = "<color=#e8d9bb>ตึก...</color>",
  ui_story_5024_50240501_131_dialog_content = "คุณวิกตอเรีย!",
