  ui_story_5024_50240801_80_dialog_content = "อย่าเหม่อสิ! ตั้งสติหน่อย!",
  ui_story_5024_50240801_81_dialog_content = "ไม่จริง... มันไม่ควรเป็นแบบนี้นี่นา...",
  ui_story_5024_50240801_82_dialog_content = "ที่ฉันเคยเห็นมันไม่ใช่แบบนี้... มันไม่น่าเป็นแบบนี้ได้...",
  ui_story_5024_50240801_83_dialog_content = "เธอไม่ใช่นักแสดง! เธอคือ... อะไรบางอย่างที่ฉันไม่รู้จัก...",
  ui_story_5024_50240801_84_dialog_content = "รีบเข้าไปช่วยเธอกันเถอะ!",
  ui_story_5024_50240801_85_dialog_content = "ถึงเลนอร์อยากเข้าไปในโรงละคร แต่ก็ไม่ควรจะเข้าด้วยวิธีน่ากลัวแบบนี้!",
  ui_story_5024_50240801_86_dialog_content = "เลนอร์... จะได้เจอแม่แล้วใช่มั้ย?",
  ui_story_5024_50240802_1_dialog_content = "เลนอร์! เลนอร์!",
  ui_story_5024_50240802_2_dialog_content = "<color=#e8d9bb>ปึง!</color>",
  ui_story_5024_50240802_3_dialog_content = "ประตูโรงละครปิดอีกแล้ว...",
  ui_story_5024_50240802_4_dialog_content = "มันเปิดประตูออกมา... เพื่อดึงตัวเลนอร์เข้าไปงั้นเหรอ...?",
  ui_story_5024_50240802_5_dialog_content = "ฉันไม่เคยเห็นโรงละครลักพาตัวคนมาก่อนเลย",
  ui_story_5024_50240802_6_dialog_content = "แสดงว่ามันมีความนึกคิดของตัวเอง... ใช่แล้ว ต้องเป็นแบบนั้นแน่ ๆ",
  ui_story_5024_50240802_7_dialog_content = "มันอยากได้ตุ๊กตาเด็กผู้หญิงตัวนั้น...",
  ui_story_5024_50240802_8_dialog_content = "เพราะอะไรกันล่ะ?",
  ui_story_5024_50240802_9_dialog_content = "ลองสังเกตตุ๊กตาที่จับตัวเลนอร์ดูสิ",
  ui_story_5024_50240802_10_dialog_content = "พวกมันดูคล้ายกับเลนอร์นะ ว่ามั้ย?",
  ui_story_5024_50240802_11_dialog_content = "ตุ๊กตามีชีวิตเดินทางมายังโรงละครที่เต็มไปด้วยตุ๊กตา...",
  ui_story_5024_50240802_12_dialog_content = "เธออาจจะเป็นส่วนหนึ่งของโรงละครตั้งแต่แรกแล้ว...",
  ui_story_5024_50240802_13_dialog_content = "พอได้แล้ว... เรามาหาวิธีเป็นนักแสดงดีกว่า",
  ui_story_5024_50240802_14_dialog_content = "เมย์...",
  ui_story_5024_50240802_14X1_dialog_content = "นี่เป็นครั้งแรกที่เห็นเธอร้อนใจแบบนี้... คงเป็นห่วงเลนอร์สินะ",
  ui_story_5024_50240802_14X2_dialog_content = "เปล่าซะหน่อย!",
  ui_story_5024_50240802_14X3_dialog_content = "ฉันก็แค่……",
  ui_story_5024_50240802_15_dialog_content = "เธอแซงฉันได้อีกแล้ว ฉันจะต้องเจอแม่ก่อนเธอให้ได้",
  ui_story_5024_50240802_16_dialog_content = "ฉันจะต้องเป็นคนแรกที่เจอคุณแม่...",
  ui_story_5024_50240802_17_dialog_content = "นั่นสินะ ยืนเศร้าใจอยู่ตรงนี้ก็คงไม่ได้อะไรขึ้นมา",
  ui_story_5024_50240802_18_dialog_content = "ถามเจ้าแมว ช่วยเหลือเจ้าแกะ เอาชนะเจ้านกฮูกหิมะ... ใช่มั้ย?",
  ui_story_5024_50240802_19_dialog_content = "อย่างน้อยเราก็ยังเจอสัตว์ทั้ง 3 ตัวได้ง่าย ๆ ตามฉันมาสิ",
  ui_story_5024_50240802_20_dialog_content = "\"เจ้าแมวน้อยผู้น่ารัก ทำให้ทุกสิ่งรอบตัวสดใส!♪\"",
  ui_story_5024_50240802_21_dialog_content = "\"เงามืดเกิดใต้แสงเทียน ร้องเพลงสนุกกันจนฟ้าสาง!\"",
