  ui_story_5024_50240802_23_dialog_content = "โอ๊ะ คุณเฟาสต์! ทุกคน... มาอ่านหนังสือเหรอคะ?",
  ui_story_5024_50240802_24_dialog_content = "เบริลอยู่ในสังกัดที่สอง เธอเหมาะจะเป็นแมวรึเปล่า?",
  ui_story_5024_50240802_25_dialog_content = "อื้ม เหมาะมาก!",
