  ui_story_5024_50240902_75_dialog_content = "ช่างเถอะ... ภาพวาดนี่ก็น่าจะพอแล้วล่ะมั้ง",
  ui_story_5024_50240902_76_dialog_content = "ว่าไง ไจลส์? ตอนนี้คาร์ลีนเป็นนกฮูกหิมะได้รึยัง?",
  ui_story_5024_50240902_77_dialog_content = "แน่นอน! ใครก็ตามที่จัดการเทลามองต์จอมโอหังได้ ย่อมคู่ควรที่จะได้เล่นเป็น<color=#FFB400>นกฮูกหิมะ</color>อยู่แล้ว!",
  ui_story_5024_50241001_1_dialog_content = "<color=#e8d9bb>ก๊อง ก๊อง ก๊อง ก๊อง ก๊อง...</color>",
  ui_story_5024_50241001_2_dialog_content = "เดี๋ยวนะ ระฆังนั่น... งานเลี้ยงเริ่มแล้วงั้นเหรอ?",
  ui_story_5024_50241001_3_dialog_content = "นักแสดงคนสุดท้ายอยู่ไหนเหรอ ไจลส์? เราต้องรีบไปที่เวทีแล้วนะ",
  ui_story_5024_50241001_4_dialog_content = "ถ้านายต้องร้องเพลงนั่นเหมือนเมื่อคืน เราก็ต้องเลื่อนการแสดงไปอีกวัน",
  ui_story_5024_50241001_5_dialog_content = "(ให้คาร์ลีนอยู่ในคฤหาสน์เพี้ยน ๆ นานขนาดนี้... เธอคงจะลำบากเกินทน)",
  ui_story_5024_50241001_6_dialog_content = "ฉันเห็นด้วย จะมัวเสียเวลาไม่ได้แล้ว ไจลส์ นายช่วย—",
  ui_story_5024_50241001_7_dialog_content = "อย่าเพิ่งรีบร้อนไป",
  ui_story_5024_50241001_8_dialog_content = "หมดเวลาเล่นสนุกแล้ว ไจลส์",
  ui_story_5024_50241001_9_dialog_content = "ไม่ว่าเธอจะอ้างอะไรก็ตาม ฉันคิดว่าเธอรู้อยู่แล้วใช่มั้ย ว่าต่อไปเราจะไปไหนกันต่อ?",
  ui_story_5024_50241001_10_dialog_content = "... ฮ่า... ฮ่าฮ่าฮ่าฮ่าฮ่า!",
  ui_story_5024_50241001_11_dialog_content = "เข้าใจแล้ว สุดท้ายก็เลี่ยงไม่ได้สินะ?",
  ui_story_5024_50241001_12_dialog_content = "ว-ว่าไงนะ?",
  ui_story_5024_50241001_13_dialog_content = "ถูกต้อง เรามี<color=#FFB400>การแสดงพิเศษ</color>สำหรับงานเลี้ยงคืนนี้...",
  ui_story_5024_50241001_14_dialog_content = "สวมนี่ซะสิ ไจลส์ ยังไงกฎก็ต้องเป็นกฎ...",
  ui_story_5024_50241001_15_dialog_content = "แล้วฉันก็ไม่ชอบข่มขู่ใครซะด้วย",
  ui_story_5024_50241001_16_dialog_content = "อา ไม่จำเป็นหรอก นำทางไปเลย",
  ui_story_5024_50241001_17_dialog_content = "การแสดงพิเศษ...?",
  ui_story_5024_50241001_18_dialog_content = "(ไม่เห็นมีใครบอกฉันเรื่องนี้เลย...)",
  ui_story_5024_50241001_19_dialog_content = "(เพราะคนอื่นเกลียดฉันสินะ... ต้องเป็นแบบนั้นแน่ ๆ...)",
  ui_story_5024_50241001_20_dialog_content = "ช่วยเล่าสั้น ๆ เกี่ยวกับการแสดงพิเศษนั่นให้เราฟังทีสิ เทลามองต์",
  ui_story_5024_50241001_21_dialog_content = "หึหึหึ เรื่องนั้น... ฉันบอกได้ว่าเราเตรียม \"การแสดง\" นี้มาสักพักแล้ว",
  ui_story_5024_50241001_22_dialog_content = "ที่จริง สมาชิกหลายคนในออเดอร์เริ่มวางแผนเรื่องนี้ตั้งแต่<color=#FFB400>คนกลุ่มสุดท้าย</color>เข้าโรงละคร",
  ui_story_5024_50241001_23_dialog_content = "คนกลุ่มสุดท้าย? ก็แสดงว่ารวมถึง...",
  ui_story_5024_50241001_24_dialog_content = "ไจลส์ด้วยงั้นเหรอ?",
  ui_story_5024_50241001_25_dialog_content = "ใช่",
  ui_story_5024_50241001_26_dialog_content = "แม็กม่าสีดำ ไจลส์ เป็นคนเดียวที่เข้าโรงละครแล้วออกมาได้",
  ui_story_5024_50241001_27_dialog_content = "แต่หลังจากที่ออกมา...",
  ui_story_5024_50241001_28_dialog_content = "เขาก็ทำเป็นหูทวนลม ไม่ยอมตอบคำถามของพวกเราเกี่ยวกับวิธีเข้าไปในนั้น",
  ui_story_5024_50241001_29_dialog_content = "การปิดบังสิ่งที่ตัวเองรู้นี่ไม่สมกับเป็นสุภาพบุรุษเลยนะ",
  ui_story_5024_50241001_30_dialog_content = "มาเถอะ ไจลส์ ฉันมั่นใจว่าถึงเวลาแล้วที่เธอจะต้องแบ่งปันความรู้ชิ้นนี้กับทุกคน",
  ui_story_5024_50241001_X30_dialog_content = "...",
  ui_story_5024_50241001_31_dialog_content = "อย่างไรซะ คุณวิกตอเรียก็อุตส่าห์ลำบากจัด \"ช่วงเวลาแบ่งปัน\" ครั้งนี้เพื่อเธอโดยเฉพาะ",
  ui_story_5024_50241001_32_dialog_content = "อย่าลืมล่ะ เฟาสต์ ว่านายมีหน้าที่ผู้พิพากษา",
  ui_story_5024_50241001_33_dialog_content = "ส่วนพวกเธอ... ถ้าอยากมาชมการแสดงก็เชิญได้เลย",
  ui_story_5024_50241001_34_dialog_content = "เอ่อ เฟาสต์? นี่มันยังไงกันแน่เนี่ย...?",
  ui_story_5024_50241001_35_dialog_content = "ฉันเองก็ช่วยไม่ได้เหมือนกัน นี่เป็นเรื่องที่ถูกกำหนดไว้นานแล้ว",
  ui_story_5024_50241001_36_dialog_content = "เอาล่ะ ถ้าหานักแสดงคนสุดท้ายไม่ได้ ก็คงเริ่มแสดงไม่ได้สินะ",
  ui_story_5024_50241001_37_dialog_content = "ให้ฉันช่วยพวกเธอไหม?",
  ui_story_5024_50241001_38_dialog_content = "... ก็ได้",
  ui_story_5024_50241001_39_dialog_content = "(ท่าทีเป็นมิตรเกินเหตุของเขาทำให้ฉันขนลุกยังไงก็ไม่รู้...)",
  ui_story_5024_50241001_40_dialog_content = "<color=#e8d9bb>ฮือฮา... ฮือฮา...</color>",
  ui_story_5024_50241001_41_dialog_content = "ทุกคน กรุณาเงียบด้วย",
  ui_story_5024_50241001_42_dialog_content = "โอ้ PlayerName? เธอกับเพื่อน ๆ ไปนั่งที่โต๊ะของไจลส์ได้นะ ทางซ้ายมือตรงนั้น",
  ui_story_5024_50241001_43_dialog_content = "แล้วก็ อย่าลืมนั่งทางซ้ายล่ะ เพราะเราต้องใช้พื้นที่ทางขวาสำหรับโจทก์",
  ui_story_5024_50241001_44_dialog_content = "จ-โจทก์?",
  ui_story_5024_50241001_45_dialog_content = "ในศาลยุติธรรมลูโมโพลิส โจทก์หมายถึงคนที่ฟ้องร้องคดีต่อศาลน่ะ",
  ui_story_5024_50241001_46_dialog_content = "แต่ฉันก็ไม่แน่ใจเหมือนกันว่านี่มันเรื่องอะไรกันแน่...",
  ui_story_5024_50241001_47_dialog_content = "ดูเหมือนว่าทรู ออเดอร์ จะเห็นว่าไจลส์ทำผิดอะไรสักอย่าง",
  ui_story_5024_50241001_48_dialog_content = "(จะว่าไป อีกฝั่งของห้องก็มีแต่สมาชิกทรู ออเดอร์...)",
  ui_story_5024_50241001_49_dialog_content = "(แถมยังมีหลายคนที่ไม่ได้นั่งที่โต๊ะ... พวกนั้นกำลังเป็น \"ลูกขุน\" รึเปล่านะ?)",
  ui_story_5024_50241001_50_dialog_content = "หวังว่าการแสดงนี้จะไม่นานมากนะ เพราะเราเองก็เหลือเวลาไม่เยอะแล้ว...",
  ui_story_5024_50241001_51_dialog_content = "<color=#e8d9bb>โครกก...</color>",
  ui_story_5024_50241001_52_dialog_content = "อะแฮ่ม... นอกจากนี้ ฉันคิดว่าพวกเราทุกคนก็หิวแล้วด้วย",
  ui_story_5024_50241001_53_dialog_content = "เกิดอะไรขึ้นน่ะ ไจลส์? พวกเขากล่าวหานายเรื่องอะไรเหรอ?",
  ui_story_5024_50241001_54_dialog_content = "ฮ่าฮ่า! ได้เวลาของเกมทายปัญหาแล้ว ค้างคาวมีตาแต่มองไม่เห็น งูถ้ำมีหูแต่ไม่ได้ยินเสียง...",
  ui_story_5024_50241001_55_dialog_content = "บอกฉันทีสิ อะไรมีปากแต่พูดไม่ได้?",
  ui_story_5024_50241001_56_dialog_content = "เอ่อ... ว่าไงนะ?!",
  ui_story_5024_50241001_57_dialog_content = "คำตอบคือนายยังไงล่ะ PlayerName",
  ui_story_5024_50241001_58_dialog_content = "เอาล่ะ ไปนั่งที่ตัวเองแล้วเงียบซะนะ การแสดงกำลังจะเริ่มแล้ว",
  ui_story_5024_50241001_59_dialog_content = "ยังไงซะ พวกนายมาที่นี่เพื่อเข้าโรงละครไปช่วยคนนี่นา จริงมั้ย?",
  ui_story_5024_50241001_60_dialog_content = "ฝ่ายจำเลยกรุณาเงียบก่อน",
  ui_story_5024_50241001_61_dialog_content = "<size=33>เยี่ยม ดูเหมือนว่าคุณวิกตอเรียจะมาถึงแล้ว</size>",
  ui_story_5024_50241001_62_dialog_content = "มากันพร้อมหน้าแล้วสินะ ทุกคน",
  ui_story_5024_50241001_63_dialog_content = "แต่เดิมฉันก็ไม่เห็นด้วยกับการใช้วิธีนี้ตัดสินเรื่องสำคัญในออเดอร์...",
  ui_story_5024_50241001_64_dialog_content = "เพราะมีเพียงความรู้และสัจธรรมเท่านั้น ที่เป็นสิ่งจริงแท้ไร้ข้อกังขาในโลกใบนี้",
  ui_story_5024_50241001_65_dialog_content = "แต่อย่างไรก็ตาม ไจลส์... การกระทำของเธอก่อให้เกิดความไม่พอใจในบรรดาสมาชิกของออเดอร์",
  ui_story_5024_50241001_66_dialog_content = "ฉันจึงอยากฟังรายละเอียดในเรื่องนี้ก่อนที่จะตัดสินอะไรลงไป",
  ui_story_5024_50241001_67_dialog_content = "ผู้นำสาร ช่วยอ่านคำฟ้องให้ทีได้ไหม?",
  ui_story_5024_50241001_68_dialog_content = "อะแฮ่ม ขอเสียงเพลงจงอำนวยพรแด่ทุกคน!",
  ui_story_5024_50241001_69_dialog_content = "\"หลังออกจากโรงละคร ไจลส์ก็เผยแพร่นิทานของเขาไปทั่วคฤหาสน์!\"♪",
  ui_story_5024_50241001_70_dialog_content = "\"แต่สิ่งหนึ่งที่เขาไม่ยอมเปิดปาก สิ่งเดียวที่เขาไม่กล้าบอกใคร... นั่นคือวิธีเข้าโรงละคร!\"♪",
  ui_story_5024_50241001_71_dialog_content = "\"มีคนบอกว่ามีตำราอันแสนล้ำค่าอยู่ภายใน บางคนบอกว่ามีสัจธรรมแอบแฝงอยู่ในซอกหลืบของโรงละคร!\"♪",
  ui_story_5024_50241001_72_dialog_content = "\"แต่เขาก็ยังไม่ยอมแบ่งปันความรู้นั้นกับเรา และยืนกรานเช่นนั้นเสมอ!\"♪",
  ui_story_5024_50241001_73_dialog_content = "ขอบคุณค่ะ ทุกท่าน~",
  ui_story_5024_50241001_74_dialog_content = "เข้าใจแล้ว เรามาฟังคำตัดสินของลูกขุนกันเถอะ",
  ui_story_5024_50241001_75_dialog_content = "ด-เดี๋ยวสิ คุณวิกตอเรีย! นี่มันไม่เร็วไปหน่อยรึ?",
  ui_story_5024_50241001_76_dialog_content = "หืม? ฝ่ายโจทก์มีอะไรจะเพิ่มเติมหรือ?",
  ui_story_5024_50241001_77_dialog_content = "... เพราะเรื่องทั้งหมดนี้ก็ตรงไปตรงมา ไจลส์ไม่ยอมบอกวิธีเข้าโรงละครปริศนาให้สมาชิกคนอื่น ๆ รู้ ใช่ไหม?",
  ui_story_5024_50241001_78_dialog_content = "พ-พูดแบบนั้นมันก็ใช่ครับ... แต่ถึงจะอธิบายได้ง่าย ๆ มันก็เป็นความผิดที่จะมองข้ามไม่ได้เป็นอันขาด!",
  ui_story_5024_50241001_79_dialog_content = "พันธกิจของทรู ออเดอร์ คือการเผยแผ่ความรู้ของเจ้าแห่งสัจธรรมไปทั่วดินแดน",
  ui_story_5024_50241001_80_dialog_content = "ไม่ว่าเราจะมีความเป็นมาอย่างไร เป็นเพศใด หรือชนชั้นใด ก็ล้วนมารวมตัวกันด้วยเจตนาอันดี เพื่อแบ่งปันความรู้เกี่ยวกับสัจธรรมซึ่งกันและกัน...",
  ui_story_5024_50241001_81_dialog_content = "การปกปิดข้อมูลสำคัญที่อาจเชื่อมโยงกับสัจธรรมเช่นนี้ ถือว่าไจลส์ละเมิดหลักคำสอนพื้นฐานของออเดอร์!",
  ui_story_5024_50241001_82_dialog_content = "... ฝ่ายจำเลยมีอะไรจะแก้ต่างข้อกล่าวหานี้ไหม?",
  ui_story_5024_50241001_83_dialog_content = "(ไจลส์ไม่ได้เป็นอย่างที่กล่าวหาสักหน่อย!)",
  ui_story_5024_50241001_84_dialog_content = "มีค่ะ!",
  ui_story_5024_50241001_85_dialog_content = "...หืม?",
  ui_story_5024_50241001_86_dialog_content = "ฉันไม่แน่ใจว่าเพราะเหตุใดไจลส์ถึงปฏิเสธไม่ยอมบอกวิธีเข้าโรงละครให้ภาคีได้รู้...",
  ui_story_5024_50241001_87_dialog_content = "แต่สิ่งที่ฉันบอกได้ในตอนนี้ก็คือ...",
  ui_story_5024_50241001_88_dialog_content = "ไจลส์ได้แบ่งปันความรู้นั้นกับพวกเราแล้ว",
