  ui_story_5024_50241001_90_dialog_content = "ใช่ครับ!",
  ui_story_5024_50241001_91_dialog_content = "ตามคำบอกเล่าของไจลส์ เหลืออีกขั้นตอนเดียวที่เราต้องทำ ก่อนที่เราจะมีคุณสมบัติเข้าโรงละคร...",
  ui_story_5024_50241001_92_dialog_content = "ถ้าเราทำได้ ก็จะพิสูจน์ได้ว่าไจลส์ไม่มีความผิด!",
