  ui_story_5024_50241001_101_dialog_content = "ผู้ที่ติดอยู่ในโรงละครจะสูญเสียจิตใจของตัวเองไปทีละน้อย...",
  ui_story_5024_50241001_102_dialog_content = "จนกระทั่งลืมเลือนตัวตนของตนเองไปอย่างสมบูรณ์ และเมื่อถึงตอนนั้น... พวกเขาก็จำได้แค่บทบาทที่ตัวเองได้รับ",
  ui_story_5024_50241001_103_dialog_content = "และสิ่งที่เกิดขึ้นหลังจากนั้น... ผมเองก็ไม่รู้เหมือนกัน เชื่อผมเถอะ",
  ui_story_5024_50241001_104_dialog_content = "... แต่อาจจะเป็นเพราะความบังเอิญหรือโชคชะตาพลิกผัน ทำให้ผมเป็นข้อยกเว้นเดียวที่บังเอิญออกมาจากโรงละครได้",
  ui_story_5024_50241001_105_dialog_content = "ก่อนที่ผมจะพูดได้ ผมก็รู้เนื้อเพลงเจ้าหมาขี้เซาแล้ว",
  ui_story_5024_50241001_106_dialog_content = "ผมโชคดีที่ได้รับโอกาสแสดงในโรงละคร แต่การแสดงของผมก็ไม่สมบูรณ์...",
  ui_story_5024_50241001_107_dialog_content = "ถึงอย่างไรก็ดี ผมก็ยังประคองสติเอาไว้และรอดชีวิตออกมาได้",
  ui_story_5024_50241001_108_dialog_content = "แม้แต่ในตอนนี้ ผมเองก็ยังไม่รู้ว่า \"การแสดงที่สมบูรณ์แบบ\" สำหรับโรงละครคืออะไร...",
  ui_story_5024_50241001_109_dialog_content = "ด้วยเหตุนี้ ผมจึงไม่ยอมให้ใครเข้าโรงละครและเสี่ยงชีวิตเพียงเพราะว่าอยากรู้อยากเห็น",
  ui_story_5024_50241001_110_dialog_content = "ส่วน PlayerName กับคนอื่น ๆ...",
  ui_story_5024_50241001_111_dialog_content = "พวกเขามีเหตุที่ดีที่จะเข้าโรงละคร พวกเขาต้องการช่วยชีวิตเพื่อนและครอบครัวออกจากเงื้อมมือของมัน",
  ui_story_5024_50241001_112_dialog_content = "และผมก็ตั้งใจที่จะช่วยพวกเขาอย่างเต็มที่",
  ui_story_5024_50241001_113_dialog_content = "แล้วทำไมถึงรอจนป่านนี้แล้วค่อยเล่าเรื่องนี้ให้เราฟังล่ะ?",
  ui_story_5024_50241001_114_dialog_content = "เพราะว่า...",
  ui_story_5024_50241001_115_dialog_content = "(เพราะพวกคุณไม่มีทางเข้าใจความหวาดกลัวสุดขีดที่ฉันได้เจอยังไงล่ะ...)",
  ui_story_5024_50241001_116_dialog_content = "เอาเถอะ ข้อแก้ต่างของผมก็มีเพียงเท่านี้",
  ui_story_5024_50241001_117_dialog_content = "เอาล่ะ PlayerName ดูเหมือนว่า<color=#FFB400>เงื่อนไขการเข้าโรงละคร</color>จะครบแล้ว",
  ui_story_5024_50241001_118_dialog_content = "<color=#FFB400>โซ่ตรวน</color>ที่ฉันสวมอยู่เป็นเครื่องแต่งกายสุดท้ายที่จำเป็นสำหรับละคร",
  ui_story_5024_50241001_119_dialog_content = "ต้องขออภัยด้วย คุณวิกตอเรีย รบกวนช่วยตัดสินคดีเดี๋ยวนี้เลยได้ไหม?",
  ui_story_5024_50241001_120_dialog_content = "เฟาสต์ ปลดโซ่ให้ไจลส์ทีสิ",
  ui_story_5024_50241001_121_dialog_content = "การแสดงพิจารณาคดีจบลงแต่เพียงเท่านี้",
  ui_story_5024_50241001_122_dialog_content = "ถ้าเธอกับสหายเป็นคนกลุ่มเดียวที่ได้รับอนุญาตให้สำรวจซอกมุมสุดท้ายของคฤหาสน์แห่งความจริง...",
  ui_story_5024_50241001_123_dialog_content = "PlayerName ขอความจริงจงสถิตกับเธอ! ฉันจะพยายามอย่างเต็มที่เพื่อช่วยเธอนะ",
  ui_story_5024_50241101_1_dialog_content = "ขอให้โชคดีกับการแสดงนะ PlayerName!",
  ui_story_5024_50241101_2_dialog_content = "โชคดีนะ PlayerName สนุกกับความหวาดกลัวและความสนุกสนานบนเวทีให้เต็มอิ่มเลยนะ",
  ui_story_5024_50241101_3_dialog_content = "ทำให้เต็มที่ล่ะ PlayerName...",
  ui_story_5024_50241101_4_dialog_content = "หินแห่งการล่าของฉันมันไปไหนไม่รู้ แต่ถ้ามันเข้ามารบกวนการแสดงก็ไม่ต้องตกใจนะ",
  ui_story_5024_50241101_5_dialog_content = "PlayerName เธอกับเพื่อนของเธออาจจะเป็นคนซื่อบื้อที่สุดเท่าที่ฉันรู้จัก... แต่ก็ขอให้โชคดีนะ",
  ui_story_5024_50241101_6_dialog_content = "... ที่จริงยัยแพกต์น่ะโกหก เธอต่างหากที่อยากเข้าไปในโรงละครมากกว่าใคร ไม่ใช่หินของเธอหรอก",
  ui_story_5024_50241101_7_dialog_content = "แม่นั่นหัวแข็งเหลือเกิน เอาแต่คิดว่าคฤหาสน์แห่งความจริงซ่อนอะไรพิเศษเอาไว้... อย่างเช่นที่มาของความรู้มหาศาล หรือสิ่งที่จะช่วยให้เธอเข้าใจในสัจธรรมมากขึ้น",
  ui_story_5024_50241101_8_dialog_content = "ฉันคงมาส่งเธอกับเพื่อน ๆ ได้แค่นี้ PlayerName",
  ui_story_5024_50241101_9_dialog_content = "ฉันชื่นชมความมุ่งมั่นของเธอนะ เมื่อเธอกลับมา ฉันจะฉลองให้กับ \"การกำเนิดใหม่\" ด้วยความยินดียิ่ง",
  ui_story_5024_50241101_10_dialog_content = "ขอความจริงจงสถิตกับท่าน",
  ui_story_5024_50241101_11_dialog_content = "PlayerName ที่จริงแล้ว... ตำราของฉันมีคำพยากรณ์เกี่ยวกับเธอและโรงละครด้วย...",
  ui_story_5024_50241101_12_dialog_content = "\"เอกองค์สัจธรรมแฝงอยู่ในละครที่ต้องแสดงซ้ำ \nชะตากรรมของนักแสดงเป็นปริศนา \nเช่นเดียวกับบทละครที่ยังคงค้างคา\"",
  ui_story_5024_50241101_13_dialog_content = "\"จักไม่มีผู้ใดออกจากโรงละครมา จนกว่าฉากสุดท้ายตระการตาปิดฉากลง\"",
  ui_story_5024_50241101_14_dialog_content = "ฉันก็ไม่แน่ใจว่าจะตีความยังไงเหมือนกัน... แต่สหายของเธออาจจะช่วยไขความจริงให้กระจ่างขึ้นก็ได้",
  ui_story_5024_50241101_15_dialog_content = "พวกเราทุกคนในออเดอร์จะรอเธออยู่ที่ทางเข้า และจะคอยช่วยเธอเท่าที่ทำได้",
  ui_story_5024_50241101_16_dialog_content = "ขอให้ทุกคนโชคดี",
  ui_story_5024_50241101_17_dialog_content = "ข-ขอบคุณครับ ทุกคน...!",
  ui_story_5024_50241101_18_dialog_content = "(แปลกชะมัด...)",
  ui_story_5024_50241101_19_dialog_content = "(ให้ตายฉันก็คงไม่มีทางเข้าใจคนพวกนี้ได้แน่ ๆ...)",
  ui_story_5024_50241101_20_dialog_content = "โรงละครจะเปิดแล้ว ทุกคน เตรียมของประกอบฉากให้พร้อมนะ!",
  ui_story_5024_50241101_21_dialog_content = "<color=#FFB400>แกะ</color>กับเครื่องเงิน...",
  ui_story_5024_50241101_22_dialog_content = "<color=#FFB400>แมว</color>กับเทียนไข...",
  ui_story_5024_50241101_23_dialog_content = "<color=#FFB400>นกฮูก</color>กับชุดที่ตัดจากภาพวาด...",
  ui_story_5024_50241101_24_dialog_content = "และ<color=#FFB400>สุนัข</color> กับโซ่ตรวน...",
