  ui_story_5024_50241101_26_dialog_content = "ถูกต้อง! เมื่อนักแสดงประจำที่ เดี๋ยวม่านก็จะเปิดออกแล้ว...",
  ui_story_5024_50241101_27_dialog_content = "เอาล่ะ ทุกคน เตรียมขึ้นเวทีได้เลย♪",
  ui_story_5024_50241101_28_dialog_content = "ได้เวลาก้าวเข้าสู่โรงละครแล้ว...",
  ui_story_5024_50241101_29_dialog_content = "แต่ฉันก็ไม่รู้หรอกนะ ว่าการแสดงที่ \"สมบูรณ์แบบ\" คืออะไร...",
  ui_story_5024_50241101_30_dialog_content = "คงต้องมีวิธีแหละ เอาเป็นว่าเราไปปรับกันข้างในละกัน",
  ui_story_5024_50241101_31_dialog_content = "PlayerName พูดถูก อีกอย่างนะ ถ้าเราไม่เข้าไป เราจะไม่มีโอกาสได้แสดงเลย",
  ui_story_5024_50241101_32_dialog_content = "พูดได้ดี! ไปกันเถอะ ละคร \"เจ้าหมาขี้เซา\" ที่สมบูรณ์แบบที่สุดรอให้เราไปตีความอยู่!",
  ui_story_5024_50241101_33_dialog_content = "<color=#e8d9bb>ตึก ตึก ตึก...</color>",
  ui_story_5024_50241101_34_dialog_content = "(มืดจังแฮะ... แต่ฟังจากเสียงสะท้อนแล้ว ในนี้น่าจะกว้างมาก ๆ...)",
  ui_story_5024_50241101_35_dialog_content = "(พลังจิตของฉันสัมผัสอะไรไม่ได้เลยนอกจากพวกเรา ไม่ว่าจะพยายามแค่ไหน...)",
  ui_story_5024_50241101_36_dialog_content = "(รู้สึกไม่ดีกับที่นี่เลย...)",
  ui_story_5024_50241101_37_dialog_content = "พ-พวกเธออยู่ในนี้รึเปล่า...? เลนอร์ เกรเทล... แล้วก็คุณแม่ของเลนอร์กับเมย์...?",
