  ui_story_5024_50241101_45_dialog_content = "โอย... เจ็บจัง...",
  ui_story_5024_50241101_46_dialog_content = "ต้องเย็บขาอีกแล้วแหง ๆ...",
  ui_story_5024_50241101_47_dialog_content = "เดินระวังด้วยนะทุกคน อย่าสะดุดล่ะ...",
