  ui_story_5024_50241101_52_dialog_content = "<color=#e8d9bb>สวบ สวบ สวบ...</color>",
  ui_story_5024_50241101_53_dialog_content = "อืมม... เป็นทรงกระบอกแข็ง ๆ แต่ไม่รู้ว่าคืออะไร...",
