  ui_story_5024_50241101_55_dialog_content = "...!",
  ui_story_5024_50241101_56_dialog_content = "<anim type=Shake><size=45>กรี๊ดดดดดดดด!!!</size></anim>",
  ui_story_5024_50241101_57_dialog_content = "บ-บ-บนพื้น... น-นี่มัน... มัน...!",
  ui_story_5024_50241101_58_dialog_content = "(หา?!)",
  ui_story_5024_50241101_59_dialog_content = "... อย่าเพิ่งตื่นตระหนก",
  ui_story_5024_50241101_60_dialog_content = "นี่ไม่ใช่ลำตัวคนจริง ๆ มันเป็นของตุ๊กตาน่ะ",
  ui_story_5024_50241101_61_dialog_content = "ตุ๊กตา?",
  ui_story_5024_50241101_62_dialog_content = "ทำไมทุกตัวถึงดูเหมือนเลนอร์เลยนะ?",
