  ui_story_5024_50241101_64_dialog_content = "โอ... ไม่นะ...",
  ui_story_5024_50241101_65_dialog_content = "หน้าของหุ่นนั่น... เป็นไปไม่ได้...!",
  ui_story_5024_50241101_66_dialog_content = "เป็นอะไรไป ไจลส์? ทำไมทำหน้าเหมือนเห็นผีแบบนั้นล่ะ...",
  ui_story_5024_50241101_67_dialog_content = "ย-อย่าดูนะ เมย์!!!",
  ui_story_5024_50241101_68_dialog_content = "โอ้...",
  ui_story_5024_50241101_69_dialog_content = "เดี๋ยวนะ... ตุ๊กตาตัวนี้มันเหมือนกับ...",
  ui_story_5024_50241101_70_dialog_content = "<size=33><color=#FFB400>แม่</color>?</size>",
  ui_story_5024_50241101_71_dialog_content = "อย่างนี้นี่เอง...",
  ui_story_5024_50241101_72_dialog_content = "นี่คือ... ชะตากรรมของคนที่ไม่สามารถแสดงได้อย่างสมบูรณ์แบบสินะ...",
  ui_story_5024_50241101_73_dialog_content = "ตอนแรกก็จะถูกขัง จากนั้นก็สูญเสียจิตใจไปเรื่อย ๆ...",
  ui_story_5024_50241101_74_dialog_content = "สุดท้ายก็ลืมว่าตัวเองเคยเป็นใคร คิดว่าตัวเองเป็นตัวละครตัวนั้นโดยสมบูรณ์...",
  ui_story_5024_50241101_75_dialog_content = "แล้วพวกเขาก็กลายเป็นสิ่งนี้...",
  ui_story_5024_50241101_76_dialog_content = "กลายเป็นตุ๊กตา... ตุ๊กตาไร้ชีวิตที่มีต้นแบบจากร่างเดิม...",
  ui_story_5024_50241101_77_dialog_content = "ม-แม่...",
  ui_story_5024_50241101_78_dialog_content = "ไม่นะ... แม่คะ ทำไมถึงเป็นแบบนี้...",
  ui_story_5024_50241101_79_dialog_content = "ไม่เอานะ... ไม่เอา!",
  ui_story_5024_50241101_80_dialog_content = "(โหดร้ายเหลือเกิน...)",
  ui_story_5024_50241101_81_dialog_content = "(ขอเทพแห่งแสงสว่างจงช่วยเหลือวิญญาณผู้น่าสงสารเหล่านี้ให้พบกับสันติด้วยเถิด...)",
  ui_story_5024_50241101_82_dialog_content = "<anim type=Shake>เอี๊ยด...</anim>",
  ui_story_5024_50241101_83_dialog_content = "<anim type=Shake>ครืด...</anim>",
  ui_story_5024_50241101_84_dialog_content = "ระวังนะทุกคน! มีบางอย่างเคลื่อนไหวอยู่แถวนี้!",
  ui_story_5024_50241101_85_dialog_content = "<anim type=Shake><size=45>ครืด... ครืด...</size></anim>",
  ui_story_5024_50241101_86_dialog_content = "ฝันร้ายนั่นอีกแล้วเหรอ...?",
  ui_story_5024_50241101_87_dialog_content = "ทุกคนพร้อมรึยัง? PlayerName?",
  ui_story_5024_50241101_88_dialog_content = "อย่างน้อยการทำลายพวกเขา ก็เป็นหนทางที่จะช่วยให้พวกเขาไปสู่สุคติ...",
  ui_story_5024_50241102_1_dialog_content = "<anim type=Shake>ครืด... ติ๊ก...</anim>",
  ui_story_5024_50241102_2_dialog_content = "*หอบ* PlayerName... ที่นี่อันตรายเกินไป...",
