  ui_story_5024_50241102_4_dialog_content = "ถ้าพวกเธอยัง...",
  ui_story_5024_50241102_5_dialog_content = "ไม่สิ... พวกเธอจะต้องไม่เป็นไร ฉันมั่นใจ",
  ui_story_5024_50241102_6_dialog_content = "เอาล่ะ ในเมื่อพวกเธอไม่ได้อยู่ในกลุ่มผู้ชม หรือทางเดินระหว่างที่นั่ง...",
  ui_story_5024_50241102_7_dialog_content = "ก็เหลือแค่สองที่ คือหลังเวที... หรือไม่ก็บนเวที",
  ui_story_5024_50241102_8_dialog_content = "... พลังลึกลับจะเริ่มกัดกินจิตใจของเราอย่างช้า ๆ",
  ui_story_5024_50241102_9_dialog_content = "ถ้าเลนอร์กับเกรเทลถูกขังอยู่ในนี้...",
  ui_story_5024_50241102_10_dialog_content = "...",
  ui_story_5024_50241102_11_dialog_content = "PlayerName... คาร์ลีน... เมย์...",
  ui_story_5024_50241102_12_dialog_content = "ไม่ว่าจะเกิดอะไรขึ้น เธอจะต้องจำชื่อและตัวตนของพวกเราทุกคนในกลุ่มให้ได้ เข้าใจมั้ย?",
  ui_story_5024_50241102_13_dialog_content = "ได้เลย",
  ui_story_5024_50241102_14_dialog_content = "ไม่ต้องห่วง ฉันจะคอยตรวจสอบสติของทุกคนระหว่างที่เราอยู่ในนี้ ฉันจะไม่ยอมให้ใครเป็นอันตราย",
  ui_story_5024_50241102_15_dialog_content = "ยอดเลย เอาล่ะ... มากับฉันสิ",
  ui_story_5024_50241102_16_dialog_content = "<color=#e8d9bb>โรงละคร หลังเวที...</color>",
  ui_story_5024_50241102_17_dialog_content = "เป็นสถานที่ที่ประหลาดอะไรยังงี้...",
  ui_story_5024_50241102_18_dialog_content = "มันทำให้ฉันรู้สึกกระอักกระอ่วนมาก ๆ เลย...",
  ui_story_5024_50241102_19_dialog_content = "ถ้ากลัว ลองตะโกนเรียกพวกเขาดีมั้ย?",
  ui_story_5024_50241102_20_option_content = "เลนอร์!",
  ui_story_5024_50241102_21_dialog_content = "เลนอร์! เธออยู่ในนี้รึเปล่า?",
  ui_story_5024_50241102_22_dialog_content = "เราเข้าโรงละครได้แล้วนะ! เรามาช่วยเธอแล้ว...",
  ui_story_5024_50241102_23_option_content = "เกรเทล!",
  ui_story_5024_50241102_24_dialog_content = "เกรเทล! เธออยู่ในนี้รึเปล่า?",
  ui_story_5024_50241102_25_dialog_content = "ที่นี่อันตรายมากนะ! เราเป็นห่วงเธอ ก็เลย...",
  ui_story_5024_50241102_26_dialog_content = "<color=#e8d9bb>สวบ... สวบ...</color>",
  ui_story_5024_50241102_27_dialog_content = "มีคนอยู่ที่นี่จริง ๆ ด้วย!",
  ui_story_5024_50241102_28_dialog_content = "เธออยู่ตรงหน้าเรานี่เอง!",
  ui_story_5024_50241102_29_dialog_content = "ขอโทษที่ให้คอยนานนะ...",
  ui_story_5024_50241102_30_dialog_content = "โอ... คุณนี่เอง PlayerName... แล้วก็... ทุก ๆ คน...",
  ui_story_5024_50241102_31_dialog_content = "ในที่สุดทุกคนก็หาเลนอร์เจอ... เลนอร์... ดีใจมากเลย...!",
  ui_story_5024_50241102_32_dialog_content = "(เยี่ยม ดูเหมือนเลนอร์ยังสติดีอยู่!)",
  ui_story_5024_50241102_33_dialog_content = "(เดี๋ยวนะ... ร่างกายของเธอ...)",
  ui_story_5024_50241102_34_dialog_content = "อ๊ะ... ขอโทษนะ น่าอายจัง...",
  ui_story_5024_50241102_35_dialog_content = "เลนอร์ยังไม่พร้อมที่จะพบใคร...",
  ui_story_5024_50241102_36_dialog_content = "เพราะว่า... เลนอร์ยังปรับตัวกับ<color=#FFB400>ร่างใหม่</color>ไม่ได้",
  ui_story_5024_50241102_37_dialog_content = "อะไรนะ... หรือว่า...",
  ui_story_5024_50241102_38_dialog_content = "หลังจากเลนอร์ถูกพามาที่นี่ ก็หมดสติไปพักหนึ่ง",
  ui_story_5024_50241102_39_dialog_content = "พอฟื้นขึ้นมา เลนอร์ก็มานั่งอยู่ที่นี่ซะแล้ว",
  ui_story_5024_50241102_40_dialog_content = "พวกเด็ก ๆ ตรงโน้น... ก็เคยเป็นเหมือนเลนอร์ในอดีต",
  ui_story_5024_50241102_41_dialog_content = "\"ได้ถูกไขลานอีกครั้งคือความสุข ข้อต่อหลุดหลวมคือความเจ็บปวด...\"",
  ui_story_5024_50241102_42_dialog_content = "เด็กพวกนั้นรู้เพียงแค่นี้ พวกเธอไม่เคยสัมผัสกับอารมณ์ความรู้สึกที่แท้จริง",
  ui_story_5024_50241102_43_dialog_content = "และเลนอร์ก็รู้ว่ามันรู้สึกยังไง...",
  ui_story_5024_50241102_44_dialog_content = "ไม่มีพลังพิเศษของออโรเรียน และไม่ได้มีพละกำลังหรือความอดทนเหมือนอิคลิพไซท์...",
  ui_story_5024_50241102_45_dialog_content = "ไม่มีแม้แต่ร่างกายที่แท้จริงด้วยซ้ำ",
  ui_story_5024_50241102_46_dialog_content = "แต่ตอนนี้... เมื่อข้อต่อและกลไกเฟืองของเลนอร์<color=#FFB400>หายไป</color> ก็ได้แต่สงสัย... ว่าตัวเองคืออะไรกันแน่?",
  ui_story_5024_50241102_47_dialog_content = "PlayerName... ช่วยบอกเลนอร์หน่อยเถอะ",
  ui_story_5024_50241102_48_dialog_content = "(จิตใจของเลนอร์... ยังได้รับผลกระทบจากคฤหาสน์อยู่งั้นเหรอ?)",
  ui_story_5024_50241102_49_dialog_content = "เลนอร์... ที่เธอต้องทำ... ก็แค่ฟังเสียงหัวใจของตัวเอง",
  ui_story_5024_50241102_50_dialog_content = "ฟังเสียง... หัวใจของเลนอร์?",
  ui_story_5024_50241102_51_dialog_content = "ไม่มีใครบอกว่าเธอเกิดมาเป็นตุ๊กตา แล้วก็ไม่มีใครบอกว่าเธอเกิดมาเป็นออโรเรียน",
  ui_story_5024_50241102_52_dialog_content = "ถ้าสิ่งที่เธอใฝ่ฝันมาตลอดคือการมีร่างกายจริง ๆ...",
  ui_story_5024_50241102_53_dialog_content = "ทำไมไม่ทิ้งความคลางแคลงใจแล้วยอมรับตัวตนใหม่ของเธอล่ะ?",
  ui_story_5024_50241102_54_dialog_content = "แบบนี้เองสินะ...",
  ui_story_5024_50241102_55_dialog_content = "เลนอร์... จะพยายามทำความเข้าใจคำพูดของคุณค่ะ",
  ui_story_5024_50241102_56_dialog_content = "... งั้นเหรอ",
  ui_story_5024_50241102_57_dialog_content = "ดูเหมือนว่า... ในที่สุด สิ่งที่แม่ของเธอปรารถนาก็เป็นความจริง...",
  ui_story_5024_50241102_58_dialog_content = "สิ่งที่แม่ของเธอปรารถนา?",
  ui_story_5024_50241102_59_dialog_content = "ใช่...",
  ui_story_5024_50241102_60_dialog_content = "ตอนที่ฉันพบแม่ของเธอครั้งแรก เธอดูท่าทางสิ้นหวัง... สิ้นหวังจนแทบจะถอดใจ...",
  ui_story_5024_50241102_61_dialog_content = "เธอบอกว่าเธอกำลังตามหาสิ่งที่ไม่น่าจะมีอยู่จริง...",
  ui_story_5024_50241102_62_dialog_content = "นั่นก็คือวิธีเปลี่ยนลูกสาวคนโตที่สูญเสียร่างกาย ให้กลับเป็นออโรเรียนธรรมดา",
  ui_story_5024_50241102_63_dialog_content = "มันเป็นสิ่งที่ไม่สามารถทำได้ในโลกของเรา แต่ถ้าเป็นที่นี่...",
  ui_story_5024_50241102_64_dialog_content = "ก็อาจสำเร็จได้ แม้โอกาสจะน้อยมากก็ตาม",
  ui_story_5024_50241102_65_dialog_content = "...แม่ของเธอต้องการให้โรงละครลบเลือนตัวตนก่อนหน้าของเลนอร์อย่างสมบูรณ์... เพื่อที่เธอจะได้มีตัวตนใหม่ในฐานะออโรเรียนงั้นเหรอ?",
