  ui_story_5024_50241102_68_dialog_content = "เธอจะต้องอยู่ที่นี่ให้นานที่สุด เพื่อปลูกฝังตัวตนใหม่ให้กับจิตใจของเลนอร์",
  ui_story_5024_50241102_69_dialog_content = "เงามืดที่ลากเลนอร์เข้าไปก่อนหน้านี้... จะต้องเป็นสติสัมปชัญญะที่เหลืออยู่ของแม่เธออย่างแน่นอน",
