  ui_story_5024_50241201_10_dialog_content = "เกรเทล!",
  ui_story_5024_50241201_11_dialog_content = "<size=33>… ระวังนะ PlayerName เราต้องเช็กให้แน่ใจว่าเธอยังสติดีอยู่รึเปล่า</size>",
