  ui_story_5024_50241201_28_dialog_content = "เด็กเข้มแข็งอย่างเกรเทลคงไม่อยากยอมรับ ว่าตัวเองก็ไม่รู้ว่าเข้ามาได้ยังไง",
  ui_story_5024_50241201_29_dialog_content = "(ช่างเถอะ ยังไงตอนนี้สิ่งสำคัญที่สุดก็คือต้องเล่นละครให้จบ!)",
  ui_story_5024_50241201_30_dialog_content = "เกรเทล เธอเป็นคนเก่งมากอยู่แล้ว คงเข้าใจสิ่งที่ฉันจะพูดนะ...",
