  ui_story_5024_50241201_32_dialog_content = "(อดทนไว้ ทำใจร่ม ๆ หายใจเข้าลึก ๆ นะ PlayerName…)",
  ui_story_5024_50241201_33_dialog_content = "ตอนนี้เราอยู่ในโรงละครที่ไม่ปล่อยให้ผู้มาเยือนกลับออกไปง่าย ๆ",
  ui_story_5024_50241201_34_dialog_content = "คฤหาสน์แห่งความจริงที่อยู่นอกโรงละครนี้เป็นคฤหาสน์ของทรู ออเดอร์",
  ui_story_5024_50241201_35_dialog_content = "แต่ว่า แม้แต่พวกนั้นก็เข้ามาไม่ได้ง่าย ๆ ... เพราะฉะนั้น เกรเทล",
  ui_story_5024_50241201_36_dialog_content = "เธอเป็นเด็กโชคดีที่ถูกเลือกนะ!",
  ui_story_5024_50241201_37_dialog_content = "ฉันถูกเลือก? แสดงว่าคุณก็ถูกเลือกเหมือนกันงั้นเหรอ?",
  ui_story_5024_50241201_38_dialog_content = "ใช่ เราต้องร่วมมือกันเพื่อเล่นละคร \"เจ้าหมาขี้เซา\" ให้สำเร็จ!",
  ui_story_5024_50241201_39_dialog_content = "นี่เป็นวิธีเดียวที่จะออกจากที่นี่ได้",
  ui_story_5024_50241201_40_dialog_content = "พี่สาวของเธอตามหาเธออยู่นะ รู้มั้ยว่าวาเลนเซียเป็นห่วงเธอแค่ไหน!",
  ui_story_5024_50241201_41_dialog_content = "...",
  ui_story_5024_50241201_42_dialog_content = "เธอคือคนแรกที่เข้ามาในโรงละคร ดังนั้นเธอจะต้องรับบท<color=#FFB400>เจ้านาย</color>",
  ui_story_5024_50241201_43_dialog_content = "เธอทำได้มั้ย เกรเทล?",
  ui_story_5024_50241201_44_dialog_content = "... ได้ ฉันจะเล่นเป็น \"เจ้านาย\"...",
  ui_story_5024_50241201_45_dialog_content = "เกรเทล เธอสงสัยหรือกังวลอะไรรึเปล่า?",
  ui_story_5024_50241201_46_dialog_content = "ไม่มี มาเริ่มกันเถอะ",
  ui_story_5024_50241201_47_dialog_content = "(นี่มัน... ง่าย ๆ ยังงี้เลยเหรอ?)",
  ui_story_5024_50241201_48_dialog_content = "ไจลส์ ทุกคนพร้อมแล้ว",
  ui_story_5024_50241201_49_dialog_content = "นักแสดง ของประกอบฉาก และผู้ชม…",
  ui_story_5024_50241201_50_dialog_content = "เลนอร์จะปรบมือให้กำลังใจทุกคนเองค่ะ!",
  ui_story_5024_50241201_51_dialog_content = "จากประสบการณ์ก่อนหน้านี้ ฉันขอแนะนำอะไรหน่อยก็แล้วกัน…",
  ui_story_5024_50241201_52_dialog_content = "ข้อแรก เมื่อละครเริ่มแล้ว จะไม่สามารถพักหรือหยุดกลางคันได้…",
  ui_story_5024_50241201_53_dialog_content = "ไม่ว่าอะไรจะเกิดขึ้นระหว่างการแสดง เราจะต้องปรับตัวให้ทันและรับมือกับมันให้ได้",
  ui_story_5024_50241201_54_dialog_content = "ข้อสอง เราต้องแสดงส่วนของนิทานส่วนที่เลือนหายไปด้วย...",
  ui_story_5024_50241201_55_dialog_content = "การด้นสดของเราจะต้องเหมาะกับสถานการณ์ที่สุด ห้ามปล่อยข้ามไปเด็ดขาด",
  ui_story_5024_50241201_56_dialog_content = "ข้อสุดท้าย นี่ไม่ใช่เกมสนุก ๆ...",
  ui_story_5024_50241201_57_dialog_content = "จงศรัทธาในบทบาทของตัวเอง และเชื่อมั่นในศรัทธานั้น",
  ui_story_5024_50241201_58_dialog_content = "ได้เลย เรื่อง \"จริงจัง\" ฉันไม่เคยพลาดอยู่แล้ว",
  ui_story_5024_50241201_59_dialog_content = "ฉัน... ฉันไม่กลัวหรอก",
  ui_story_5024_50241201_60_dialog_content = "...",
  ui_story_5024_50241201_61_dialog_content = "ดีมาก! ถ้าเราร่วมมือกัน รับรองว่าต้องสำเร็จแน่ ๆ",
  ui_story_5024_50241201_62_dialog_content = "ฮ่าฮ่าฮ่าฮ่า เตรียมตัวให้พร้อมล่ะ ทุกคน! ม่านกำลังจะเปิดแล้ว...",
  ui_story_5024_50241201_63_dialog_content = "<color=#e8d9bb>ครืด... ครืด...</color>",
  ui_story_5024_50241201_64_dialog_content = "<color=#e8d9bb>พวกเราภูมิใจเสนอ ละครเรื่อง \"เจ้าหมาขี้เซา\" เชิญรับชมได้เลย!</color>",
  ui_story_5024_50241201_65_dialog_content = "<color=#e8d9bb>\"สร้างบ้านกันเถอะ...มาสร้างบ้านกัน...\"</color>",
  ui_story_5024_50241201_66_dialog_content = "<color=#e8d9bb>\"สร้างบ้านงดงามแสนสวย♪\"</color>",
  ui_story_5024_50241201_67_dialog_content = "<color=#e8d9bb>\"ไม่ใช่เพื่อเจ้าเมือง ไม่ใช่เพื่อจอมทัพ...\"</color>",
  ui_story_5024_50241201_68_dialog_content = "<color=#e8d9bb>\"แต่เพื่อเจ้าหมาแก่ขี้เซาได้นอนข้างเตาผิง♪\"</color>",
  ui_story_5024_50241201_69_dialog_content = "<color=#e8d9bb>\"เปิดสิ เปิดออกมา...\"</color>",
  ui_story_5024_50241201_70_dialog_content = "<color=#e8d9bb>\"เปิดประตูหน้าบ้าน♪\"</color>",
  ui_story_5024_50241201_71_dialog_content = "<color=#e8d9bb>\"เจ้าแกะ เจ้าแมว และเจ้านกฮูกหิมะผู้ไร้บ้าน...\"</color>",
  ui_story_5024_50241201_72_dialog_content = "<color=#e8d9bb>\"ล้อมรอบเจ้าหมาแก่ขี้เซาข้างเตาผิง♪\"</color>",
  ui_story_5024_50241201_73_dialog_content = "<color=#e8d9bb>\"ลั่นกลอนสิ ลั่นกลอนให้สนิท...\"</color>",
  ui_story_5024_50241201_74_dialog_content = "<color=#e8d9bb>\"รีบใส่กลอนประตูบ้าน♪\"</color>",
  ui_story_5024_50241201_75_dialog_content = "<color=#e8d9bb>\"เสียงหัวเราะจากงานเลี้ยงดังออกไปนอกหน้าต่าง...\"</color>",
  ui_story_5024_50241201_76_dialog_content = "<color=#e8d9bb>\"แต่เจ้าหมาขี้เซาข้างเตาผิงก็ไม่ตื่น♪\"</color>",
  ui_story_5024_50241201_77_dialog_content = "<color=#e8d9bb>\"ลั่นกลอนสิ ลั่นกลอนให้สนิท...\"</color>",
  ui_story_5024_50241201_78_dialog_content = "<color=#e8d9bb>\"รีบใส่กลอนประตูบ้าน♪\"</color>",
  ui_story_5024_50241201_79_dialog_content = "<color=#e8d9bb>\"ข้างในบ้านช่างอบอุ่น แม้เจ้านายจะไม่อยู่...\"</color>",
  ui_story_5024_50241201_80_dialog_content = "<color=#e8d9bb>\"อย่าไปสนใจเจ้าหมาขี้เซาข้างเตาผิง♪\"</color>",
  ui_story_5024_50241201_81_dialog_content = "<color=#e8d9bb>ลั่นกลอนสิ ลั่นกลอนให้สนิท...</color>",
  ui_story_5024_50241201_82_dialog_content = "<anim type=Shake>กรร...</anim>",
  ui_story_5024_50241201_83_dialog_content = "<anim type=Shake>กรร...</anim>",
  ui_story_5024_50241201_84_dialog_content = "<anim type=Shake><size=45>*โฮกก*</size></anim>",
  ui_story_5024_50241201_85_dialog_content = "ทำไมต้องมาตอนนี้ด้วยเนี่ย?",
  ui_story_5024_50241201_86_dialog_content = "เมย์! อย่าใจลอย!",
  ui_story_5024_50241201_87_dialog_content = "PlayerName นี่เป็นโอกาสที่ยอดมากเลยนะ!",
  ui_story_5024_50241201_88_dialog_content = "เราจับอิคลิพไซท์พวกนี้ขังกันเถอะ!",
  ui_story_5024_50241201_89_dialog_content = "อา! น่าสนุก น่าสนุกดีนี่!",
  ui_story_5024_50241201_90_dialog_content = "เป็นไอเดียที่บรรเจิดจริง ๆ! เราจะสั่งสอนพวกอิคลิพไซท์ให้รู้สำนึก!",
  ui_story_5024_50241402_1_dialog_content = "<anim type=Shake>กรร...</anim>",
  ui_story_5024_50241402_2_dialog_content = "แฮ่ก แฮ่ก...",
  ui_story_5024_50241402_3_dialog_content = "หึหึ...",
  ui_story_5024_50241402_4_dialog_content = "(ได้ผลมั้ย?)",
  ui_story_5024_50241402_5_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5024_50241402_6_dialog_content = "<color=#e8d9bb>\"ลั่นกลอนสิ ลั่นกลอนให้สนิท...\"</color>",
  ui_story_5024_50241402_7_dialog_content = "<color=#e8d9bb>ขังฝูงอิคลิพไซท์เอาไว้</color>",
  ui_story_5024_50241402_8_dialog_content = "(สำเร็จ!)",
  ui_story_5024_50241402_9_dialog_content = "<color=#e8d9bb>\"ทุกตัวนอนเรียงแถว น่ารักจับใจ...</color>",
  ui_story_5024_50241402_10_dialog_content = "<color=#e8d9bb>\"แกะ แมว นกฮูกหิมะ และเจ้าหมาขี้เซาว่านอนสอนง่าย♪\"</color>",
  ui_story_5024_50241402_11_dialog_content = "<color=#e8d9bb>\"แกะ แมว นกฮูกหิมะ และเจ้าหมาขี้เซาว่านอนสอนง่าย♪\"</color>",
  ui_story_5024_50241402_12_dialog_content = "<color=#e8d9bb>ครืด... ครืด...</color>",
  ui_story_5024_50241402_13_dialog_content = "แฮ่ก แฮ่ก แฮ่ก",
  ui_story_5024_50241402_14_dialog_content = "แฮ่ก... แฮ่ก...",
  ui_story_5024_50241402_15_dialog_content = "(ไม่มีปัญหา... ไม่มี ไม่มี ไม่มีปัญหา ทุกอย่างสมบูรณ์แบบ...)",
  ui_story_5024_50241402_16_dialog_content = "(เป็นความเงียบที่ยาวนาน... เหมือนกับเวลาถูกหยุดเอาไว้...)",
  ui_story_5024_50241402_17_dialog_content = "(ฉันได้ยินเสียงหายใจของพวกเธอ และความรู้สึกเย็นวาบหลังจากที่รอดมาได้อย่างหวุดหวิด...)",
  ui_story_5024_50241402_18_dialog_content = "(เราทำสำเร็จรึเปล่า?)",
  ui_story_5024_50241402_19_dialog_content = "<size=45><color=#e8d9bb>ปัง...</color></size>",
  ui_story_5024_50241402_20_dialog_content = "<size=45>อ๊ะ!</size>",
  ui_story_5024_50241402_21_dialog_content = "ยอดมาก PlayerName! เป็นการแสดงที่วิเศษมาก!",
  ui_story_5024_50241402_22_dialog_content = "มาสิ! โค้งคำนับให้ผู้ชมกัน!",
  ui_story_5024_50241402_23_dialog_content = "<color=#e8d9bb>*ปรบมือ*</color>",
  ui_story_5024_50241402_24_dialog_content = "อา!",
  ui_story_5024_50241402_25_dialog_content = "เมื่อกี้ที่ม่านปิดลงมา เลนอร์เป็นห่วงทุกคนมากเลย!",
  ui_story_5024_50241402_26_dialog_content = "เมย์ คงจะกลัวสินะ!",
  ui_story_5024_50241402_27_dialog_content = "เลนอร์...",
  ui_story_5024_50241402_28_dialog_content = "ฮืออออ... เมย์กลัวมากเลย!",
  ui_story_5024_50241402_29_dialog_content = "ฟู่... ของกล้วย ๆ…",
  ui_story_5024_50241402_30_dialog_content = "PlayerName เราทำสำเร็จแล้ว!",
  ui_story_5024_50241402_31_dialog_content = "(คาร์ลีนเหงื่อออกเต็มหน้าเลย...)",
  ui_story_5024_50241402_32_dialog_content = "คาร์ลีน ทุกคนพยายามเต็มที่จริง ๆ",
  ui_story_5024_50241402_33_dialog_content = "ส่วนเกรเทล...",
  ui_story_5024_50241402_34_dialog_content = "(...)",
  ui_story_5024_50241402_35_dialog_content = "...!!!",
  ui_story_5024_50241402_36_dialog_content = "เกรเทล... เกรเทลไปไหนแล้ว?",
  ui_story_5024_50241402_37_dialog_content = "... เกรเทล?! เกรเทล!!!",
  ui_story_5024_50241402_38_dialog_content = "เลิกเล่นได้แล้ว! ออกมาเถอะ เราจะไปแล้วนะ!",
  ui_story_5024_50241402_39_dialog_content = "เลนอร์ เธอเห็นเกรเทลเดินออกไปจากเวทีรึเปล่า?",
  ui_story_5024_50241402_40_dialog_content = "ไม่นะ ไม่เห็นเลย",
  ui_story_5024_50241402_41_dialog_content = "ฉันตั้งใจดูตลอด ไม่มีใครออกไปจากเวทีเลยนะคะ...",
  ui_story_5024_50241402_42_dialog_content = "อา!",
  ui_story_5024_50241402_43_dialog_content = "หรือว่า...",
  ui_story_5024_50241402_44_dialog_content = "<color=#e8d9bb>ครืนน...</color>",
  ui_story_5024_50241402_45_dialog_content = "<color=#e8d9bb>ครืนน... ครืนน...</color>",
  ui_story_5024_50241402_46_dialog_content = "แรงสั่นสะเทือนรุนแรงนี่มันอะไรกัน!",
  ui_story_5024_50241402_47_dialog_content = "(ไม่นะ!)",
  ui_story_5024_50241402_48_dialog_content = "ทุกคน! รีบออกจากที่นี่!",
  ui_story_5024_50241402_49_dialog_content = "อย่าเข้าใกล้เวทีนะ!",
  ui_story_5024_50241501_1_dialog_content = "<color=#e8d9bb>ตูม...</color>",
  ui_story_5024_50241501_2_dialog_content = "<size=45>ทางนี้!</size>",
  ui_story_5024_50241501_3_dialog_content = "เด็กคนไหนอยากออกไปงั้นรึ?",
  ui_story_5024_50241501_4_dialog_content = "พวกเด็กดื้อที่พยายามหนีจากบ้านแสนสวย…",
  ui_story_5024_50241501_5_dialog_content = "ฉันจะจับขังให้หมด!",
  ui_story_5024_50241501_6_dialog_content = "พ-พูดอะไรน่ะ? ละครจบแล้วไม่ใช่เหรอ",
  ui_story_5024_50241501_7_dialog_content = "จบงั้นเรอะ?",
  ui_story_5024_50241501_8_dialog_content = "หึหึหึหึ...",
  ui_story_5024_50241501_9_dialog_content = "<size=45>ยังเร็วเกินไป!</size>",
  ui_story_5024_50241501_10_dialog_content = "PlayerName เราจะมัวเสียเวลาไม่ได้แล้วนะ!",
  ui_story_5024_50241501_11_dialog_content = "ดูสิ!",
  ui_story_5024_50241501_12_dialog_content = "คฤหาสน์แห่งความจริงกำลังสลายตัว...",
  ui_story_5024_50241501_13_dialog_content = "ละครเรื่องนี้ยังห่างไกลจากตอนจบนัก!",
  ui_story_5024_50241501_14_dialog_content = "ในเมื่อพวกเธอเข้ามาในโรงละครของฉันแล้ว…",
  ui_story_5024_50241501_15_dialog_content = "ในฐานะเจ้าบ้าน ฉันก็ต้องต้อนรับให้เต็มที่!",
  ui_story_5024_50241501_16_dialog_content = "ม่านเวทีน่ะ เปิดออกตั้งแต่วินาทีแรกที่พวกเธอเข้ามาในโลกแห่งโรงละครแล้ว!",
  ui_story_5024_50241501_17_dialog_content = "… ทำไมยืนนิ่งแบบนั้นล่ะ?",
  ui_story_5024_50241501_18_dialog_content = "อยากให้ \"เจ้านาย\" ผู้นี้สั่งสอนบทเรียนหรือไง?",
  ui_story_5024_50241501_19_dialog_content = "เจ้านาย?",
  ui_story_5024_50241501_20_dialog_content = "ไม่นะ... จิตใจของเกรเทลถูกครอบงำ!",
  ui_story_5024_50241501_21_dialog_content = "เธอเชื่อว่าตัวเองเป็นนายของโรงละครไปเสียแล้ว!",
  ui_story_5024_50241501_22_dialog_content = "เมื่อกี้ใครตะโกนเสียงดังน่ะ?",
  ui_story_5024_50241501_23_dialog_content = "...",
  ui_story_5024_50241501_24_dialog_content = "ถึงคฤหาสน์นี่จะประหลาดไปหน่อย แต่ฉันก็เป็นคนหามันเจอ",
  ui_story_5024_50241501_25_dialog_content = "(ที่ผ่านมา... เธอคงโดนบทละครครอบงำตั้งแต่แรกแล้ว...)",
  ui_story_5024_50241501_26_dialog_content = "PlayerName ม่านเปิดแล้ว รีบทำให้เธอได้สติเร็วเข้า!",
  ui_story_5024_50241501_27_dialog_content = "ไม่งั้นนายจะพาเธอออกไปไม่ได้นะ!",
  ui_story_5024_50241501_28_dialog_content = "\"ออกไป\" งั้นรึ?",
  ui_story_5024_50241501_29_dialog_content = "ฉันเริ่มจะหมดความอดทนแล้วนะ ต้องพูดซ้ำอีกกี่ครั้ง?",
  ui_story_5024_50241501_30_dialog_content = "\"สัตว์\" ที่มีหน้าที่สร้างความบันเทิงให้มนุษย์…",
  ui_story_5024_50241501_31_dialog_content = "<size=45>จะออกไปไหนไม่ได้ทั้งนั้น!</size>",
  ui_story_5024_50241501_32_dialog_content = "เลนอร์! ระวัง!",
  ui_story_5024_50241501_33_dialog_content = "... อ๊ะ!",
  ui_story_5024_50241501_34_dialog_content = "ฮื้ม... ฮืม...",
  ui_story_5024_50241501_35_dialog_content = "\"ลั่นกลอนสิ ลั่นกลอนให้สนิท...\"",
  ui_story_5024_50241501_36_dialog_content = "ขัง<color=#FFB400>ทุกคน</color>ไว้...",
  ui_story_5024_50241501_37_dialog_content = "(เหมือนกับคราวที่แล้วเลย!)",
  ui_story_5024_50241501_38_dialog_content = "(ต้องลงเอยแบบนี้ทุกรอบเลยเหรอ?)",
  ui_story_5024_50241501_39_dialog_content = "PlayerName เธอกำลังผลักเราไปด้านหลังเวที!",
  ui_story_5024_50241501_40_dialog_content = "อย่าไปทางนั้นนะ!",
  ui_story_5024_50241501_41_dialog_content = "<color=#e8d9bb>ครืด... ครืด...</color>",
  ui_story_5024_50241501_42_dialog_content = "นี่มัน... ม่านกำลังเปิดขึ้นมาอีกแล้ว!",
  ui_story_5024_50241501_43_dialog_content = "ฉลาดมากเจ้าหมา!",
  ui_story_5024_50241501_44_dialog_content = "การแสดงมันไม่ได้จำกัดแค่บนเวทีแคบ ๆ นี่หรอกนะ",
  ui_story_5024_50241501_45_dialog_content = "เด็กดื้อที่สมควรดัดนิสัย…",
  ui_story_5024_50241501_46_dialog_content = "จะต้องเข้าไปอยู่หลังเวที!",
  ui_story_5024_50241501_47_dialog_content = "เด็กดื้อ...",
  ui_story_5024_50241501_48_dialog_content = "เมย์... ที่ถือเทียน... เป็นเด็กดื้อเหรอ?",
  ui_story_5024_50241501_49_dialog_content = "ไม่มีใครรักเด็กดื้อ...",
  ui_story_5024_50241501_50_dialog_content = "เจ้านาย... ไม่ชอบแมวเหรอคะ?",
  ui_story_5024_50241501_51_dialog_content = "เมย์! เมย์! ตั้งสติก่อน!",
  ui_story_5024_50241501_52_dialog_content = "หืม?",
  ui_story_5024_50241501_53_dialog_content = "ทำไมฉันพูดออกไปแบบนั้นล่ะ",
  ui_story_5024_50241501_54_dialog_content = "PlayerName ทำอะไรสักอย่างสิ!",
  ui_story_5024_50241501_55_dialog_content = "ไม่ใช่แค่สติของเมย์นะ... คฤหาสน์ทั้งหลัง... กำลังโดนพลังไร้เหตุผลนั่นทำลาย!",
  ui_story_5024_50241501_56_dialog_content = "ถ้ามันขยายออกไปเรื่อย ๆ... พวกเราไม่รอดแน่!",
  ui_story_5024_50241501_57_dialog_content = "หนีไปซ่อนยังไงก็ไม่ช่วยสินะ...",
  ui_story_5024_50241501_58_dialog_content = "ฉันว่าเราคงต้องร่วมมือกับเธอเพื่อจบ<color=#FFB400>การแสดง</color>ครั้งสุดท้ายให้ได้!",
  ui_story_5024_50241501_59_dialog_content = "ถ้าเราเอาชนะ \"เจ้านาย\" สำเร็จ ละครก็ไม่เจอจุดจบแบบนี้!",
  ui_story_5024_50241502_1_dialog_content = "แฮ่ก... แฮ่ก... แฮ่ก...",
  ui_story_5024_50241502_2_dialog_content = "อ-อึก!",
  ui_story_5024_50241502_3_dialog_content = "ได้โปรด... ปล่อยฉันไปเถอะ!",
  ui_story_5024_50241502_4_dialog_content = "หือ? เกรเทลหมดสติไปแล้ว?",
  ui_story_5024_50241502_5_dialog_content = "เกรเทล เกรเทล ตื่นสิ!",
  ui_story_5024_50241502_6_dialog_content = "เอาไงดีล่ะ PlayerName?",
  ui_story_5024_50241502_7_dialog_content = "<color=#e8d9bb>ครืด... ครืด...</color>",
  ui_story_5024_50241502_8_dialog_content = "ละครจบแล้ว พาเด็กคนนี้ไปหลังเวทีเถอะ",
  ui_story_5024_50241502_9_dialog_content = "เราจะเรียกสติเธอกลับมาด้วยวิธีเดิม",
  ui_story_5024_50241502_10_dialog_content = "<color=#e8d9bb>โรงละคร หลังเวที...</color>",
  ui_story_5024_50241502_11_dialog_content = "ปวดหัวจัง... ฉันอยู่ที่ไหนเนี่ย?",
  ui_story_5024_50241502_12_dialog_content = "เกรเทล!",
  ui_story_5024_50241502_13_dialog_content = "ได้ยินฉันรึเปล่า?",
  ui_story_5024_50241502_14_dialog_content = "พี่... พี่คะ...",
  ui_story_5024_50241502_15_dialog_content = "พี่ของฉันอยู่ไหน?",
  ui_story_5024_50241502_16_dialog_content = "...",
  ui_story_5024_50241502_17_dialog_content = "ไม่ต้องกลัวนะ เกรเทล เราจะพาเธอออกไป",
  ui_story_5024_50241502_18_dialog_content = "... PlayerName ปล่อยฉันก่อนได้มั้ย?",
  ui_story_5024_50241502_19_dialog_content = "ฉันไม่ต้องให้นายมาพยุงหรอกนะ",
  ui_story_5024_50241502_20_dialog_content = "(เยี่ยม! นี่แหละเธอคนเดิม!)",
  ui_story_5024_50241502_21_dialog_content = "เธอนี่มารยาทติดลบเหมือนเดิมเลยนะ...",
  ui_story_5024_50241502_22_dialog_content = "แต่ฉันก็ดีใจนะ ที่เธอปลอดภัย",
  ui_story_5024_50241502_23_dialog_content = "... พูดอะไรประหลาดชะมัด",
  ui_story_5024_50241502_24_dialog_content = "\"เอกองค์สัจธรรมแฝงอยู่ในละครที่ต้องแสดงซ้ำ ชะตากรรมของนักแสดงเป็นปริศนา เช่นเดียวกับบทละครที่ยังคงค้างคา\"",
  ui_story_5024_50241502_25_dialog_content = "\"จักไม่มีผู้ใดออกจากโรงละครมา จนกว่าฉากสุดท้ายตระการตาปิดฉากลง\"",
  ui_story_5024_50241502_26_dialog_content = "ฮ่าฮ่าฮ่าฮ่า! เข้าใจแล้ว!",
  ui_story_5024_50241502_27_dialog_content = "นี่คือความหมายของคำพยากรณ์สินะ...",
  ui_story_5024_50241502_28_dialog_content = "ละคร \"เจ้าหมาขี้เซา\" เริ่มต้นตั้งแต่ที่เราเดินเข้ามาในโรงละครแล้ว",
  ui_story_5024_50241502_29_dialog_content = "และวิธีเดียวที่จะทำให้การแสดงสำเร็จ...",
  ui_story_5024_50241502_30_dialog_content = "ก็คือการทำลายโซ่ตรวนของ \"เจ้านาย\" ทั้งบนเวทีและนอกเวที",
  ui_story_5024_50241502_31_dialog_content = "<size=45><color=#FFB400>ทำลายให้หมด</color>!</size>",
  ui_story_5024_50241502_32_dialog_content = "นี่คือเงื่อนไขความสำเร็จของการแสดงสินะ...",
  ui_story_5024_50241502_33_dialog_content = "(ฉันรู้แล้วล่ะ ว่าเนื้อเพลงส่วนที่เลือนหายไป มันคืออะไร...)",
  ui_story_5024_50241502_34_dialog_content = "พึมพำอะไรของนายน่ะ?",
  ui_story_5024_50241502_35_dialog_content = "เดี๋ยว! อย่าวิ่งอย่างนั้นสิ!",
  ui_story_5024_50241502_36_dialog_content = "PlayerName ตามเธอไปเถอะ!",
  ui_story_5024_50241502_37_dialog_content = "<color=#e8d9bb>โรงละคร หน้าเวที</color>",
  ui_story_5024_50241502_38_dialog_content = "แฮ่ก แฮ่ก... เกรเทล... เป็นอะไรไป?",
  ui_story_5024_50241502_39_dialog_content = "อะไรเนี่ย...?",
  ui_story_5024_50241502_40_dialog_content = "PlayerName ทำไมเป็นแบบนี้ล่ะ?",
  ui_story_5024_50241502_41_dialog_content = "เอ่อ... มีอะไรเหรอ?",
  ui_story_5024_50241502_42_dialog_content = "\"เจ้าหมาขี้เซา\"... แสดงจบแล้วเหรอ?",
  ui_story_5024_50241502_43_dialog_content = "ฉันยังไม่ได้ดูเลยนะ!",
  ui_story_5024_50241502_44_dialog_content = "ฉันอยากดูละครเรื่องนี้มากเลย... แถมยังจดบันทึกไว้ตั้งเยอะ...",
  ui_story_5024_50241502_45_dialog_content = "ฉัน...",
  ui_story_5024_50241502_46_dialog_content = "ฉัน......",
  ui_story_5024_50241502_47_dialog_content = "?!",
  ui_story_5024_50241502_48_dialog_content = "แย่แล้ว! เมย์... หลบหลังฉันเร็วเข้า!",
  ui_story_5024_50241502_49_dialog_content = "<size=33>หุหุ...</size>",
  ui_story_5024_50241502_50_dialog_content = "<size=45>ฮ่าฮ่าฮ่าฮ่า!</size>",
  ui_story_5024_50241502_51_dialog_content = "ล้อเล่นน่า โดนหลอกง่ายจัง ซื่อบื้อชะมัด",
  ui_story_5024_50241502_52_dialog_content = "นี่! ไหนพูดอีกทีซิ!",
  ui_story_5024_50241502_53_dialog_content = "ถึงฉันจะไม่ได้สติในช่วงเวลาสำคัญ แต่ฉันรู้ว่าคราวนี้ฉันเป็นหนี้ชีวิตพวกคุณแล้ว",
  ui_story_5024_50241502_54_dialog_content = "ขอบคุณมากนะคะ PlayerName คาร์ลีน แล้วก็ เอ่อ...",
  ui_story_5024_50241502_55_dialog_content = "เลนอร์...",
  ui_story_5024_50241502_56_dialog_content = "เมย์!",
  ui_story_5024_50241502_57_dialog_content = "ไจลส์~",
  ui_story_5024_50241502_58_dialog_content = "อย่างน้อยพวกเราทุกคนก็จำชื่อตัวเองได้ล่ะนะ",
  ui_story_5024_50241502_59_dialog_content = "ฉันจำอะไรไม่ค่อยได้ แต่ฝันว่าตัวเองได้ต่อสู้กับ PlayerName อีกครั้ง",
  ui_story_5024_50241502_60_dialog_content = "ทุกอย่างวุ่นวายไปหมด แถมฉันยังร่วมแสดง \"เจ้าหมาขี้เซา\" ในฝันด้วย...",
  ui_story_5024_50241502_61_dialog_content = "ไม่ว่าฝันนั่นจะเป็นยังไง พอนึกดูแล้วก็น่าเสียดายอยู่ดี",
  ui_story_5024_50241502_62_dialog_content = "... คราวหน้าฉันจะต้องดูละครให้ได้เลย!",
  ui_story_5024_50241502_63_dialog_content = "(ขออย่าให้มีคราวหน้าเลยนะ!)",
  ui_story_5024_50241502_64_dialog_content = "<color=#e8d9bb>แอ๊ดดดด...</color>",
  ui_story_5024_50241502_65_dialog_content = "ประตูเปิดแล้ว PlayerName!",
  ui_story_5024_50241502_66_dialog_content = "ทุกคน ไปจากที่นี่กันเถอะ!",
  ui_story_5024_50241502_67_dialog_content = "เพื่อน ๆ จากทรู ออเดอร์ คงอยากรู้จะแย่แล้ว ว่าเราไปเจออะไรมา!",
  ui_story_5024_50241601_1_dialog_content = "PlayerName เธอทำสำเร็จ!",
  ui_story_5024_50241601_2_dialog_content = "... ยินดีต้อนรับสู่ \"โลกแห่งความจริง\"",
  ui_story_5024_50241601_3_dialog_content = "โลกแห่งความจริง?",
  ui_story_5024_50241601_4_dialog_content = "PlayerName ฉันมีข่าวดีมาบอก",
  ui_story_5024_50241601_5_dialog_content = "เปิดหน้าต่างดูสิ...",
  ui_story_5024_50241601_6_dialog_content = "หืม?",
  ui_story_5024_50241601_7_dialog_content = "ข้างนอก...",
  ui_story_5024_50241601_8_dialog_content = "ทุกอย่างกลับมาเป็นปกติแล้ว?",
  ui_story_5024_50241601_9_dialog_content = "ฉันเชื่อว่านี่คือคำพยากรณ์ที่แท้จริงของไบเบิลโชกเลือด",
  ui_story_5024_50241601_10_dialog_content = "\"เอกองค์สัจธรรมแฝงอยู่ในละครที่ต้องแสดงซ้ำ \nชะตากรรมของนักแสดงเป็นปริศนา \nเช่นเดียวกับบทละครที่ยังคงค้างคา\"",
  ui_story_5024_50241601_11_dialog_content = "\"จักไม่มีผู้ใดออกจากโรงละครมา จนกว่าฉากสุดท้ายตระการตาปิดฉากลง\"",
  ui_story_5024_50241601_12_dialog_content = "วิธีเดียวที่จะออกจากคฤหาสน์แห่งความจริงได้ ก็คือรอให้ประตูโรงละครเปิดออกหลังจากการแสดงจบลง",
  ui_story_5024_50241601_13_dialog_content = "สัจธรรมชี้นำเราสู่หนทางที่ถูกต้องเสมอ",
  ui_story_5024_50241601_14_dialog_content = "ขอความจริงจงสถิตกับคุณ คุณวิกตอเรีย!",
  ui_story_5024_50241601_15_dialog_content = "สุภาพสตรีและสุภาพบุรุษทั้งหลาย มาเพลิดเพลินกับรางวัลแห่งความสำเร็จเถอะนะ",
  ui_story_5024_50241601_16_dialog_content = "หืม? ดูเหมือนจะมีแขกที่เราไม่คุ้นเคยอีกคนด้วยนะนี่",
  ui_story_5024_50241601_17_dialog_content = "...",
  ui_story_5024_50241601_18_dialog_content = "ก็แน่อยู่แล้ว ให้มันเป็นแบบนี้ต่อไปเถอะ",
  ui_story_5024_50241601_19_dialog_content = "แต่ฉันหมายถึงเด็กผู้หญิงผมสีขาวอีกคนต่างหากล่ะ",
  ui_story_5024_50241601_20_dialog_content = "อย่าเข้าใจฉันผิดสิ เลดี้คาร์ลีน",
  ui_story_5024_50241601_21_dialog_content = "(นี่เธอกำลังกวนฉันเล่นใช่มั้ยเนี่ย?)",
  ui_story_5024_50241601_22_dialog_content = "เอ่อ... คุณคือ...",
  ui_story_5024_50241601_23_dialog_content = "บรรณารักษ์ของห้องสมุดที่นี่เหรอคะ?",
  ui_story_5024_50241601_24_dialog_content = "(หืม?!)",
  ui_story_5024_50241601_25_dialog_content = "ฮะฮะ... สาวน้อย เธอคงสนใจหนังสือในคฤหาสน์แห่งความจริงมากเลยสินะ?",
  ui_story_5024_50241601_26_dialog_content = "ก็ ใช่ค่ะ... แล้วก็ ฉันชื่อเกรเทลค่ะ",
  ui_story_5024_50241601_27_dialog_content = "เกรเทล... ฉันจะจำชื่อนั้นไว้",
  ui_story_5024_50241601_28_dialog_content = "ถ้าเธอสนใจหนังสือพวกนี้จริง ๆ ทำไมไม่มาเข้าร่วมกับทรู ออเดอร์ ล่ะ?",
  ui_story_5024_50241601_29_dialog_content = "(คุณวิกตอเรียออกปากเชิญเธอด้วยตัวเองเลยเหรอ?)",
  ui_story_5024_50241601_30_dialog_content = "ทรู ออเดอร์... เป็นชมรมอ่านหนังสือเหรอคะ?",
  ui_story_5024_50241601_31_dialog_content = "(พูดไปเรื่อย มั่วซะไม่มี!)",
  ui_story_5024_50241601_32_dialog_content = "ฮะฮะ... จะว่าไปมันก็มองแบบนั้นได้นะ",
  ui_story_5024_50241601_33_dialog_content = "ทุกคนมีสิทธิ์และมีอิสระที่จะตีความ \"สัจธรรม\" ในแบบของตัวเอง",
  ui_story_5024_50241601_34_dialog_content = "การที่เธอเห็นมันเป็นชมรมอ่านหนังสือ ก็ไม่ใช่สิ่งที่ขัดขวางการเข้าถึงสัจธรรมแต่อย่างใด",
  ui_story_5024_50241601_35_dialog_content = "(ข-เข้าใจแล้ว!)",
  ui_story_5024_50241601_36_dialog_content = "(ฉันเริ่มเข้าใจสัจธรรมมากขึ้นแล้ว...)",
  ui_story_5024_50241601_37_dialog_content = "เอาล่ะ เฟาสต์...",
  ui_story_5024_50241601_38_dialog_content = "ครับ เลดี้วิกตอเรีย",
  ui_story_5024_50241601_39_dialog_content = "ช่วยพาพวกเขาไปที่ห้องจัดเลี้ยงด้วย",
  ui_story_5024_50241601_40_dialog_content = "(ดูเหมือนฉันจะเข้าใจคนจากทรู ออเดอร์ มากขึ้นแล้ว...)",
  ui_story_5024_50241601_41_dialog_content = "(พวกเขาไม่สนใจวิธีเผยแผ่ความรู้ วิธีได้มาซึ่งความรู้ และไม่สนใจว่าจะถูกมองอย่างไร...)",
  ui_story_5024_50241601_42_dialog_content = "(แม้จะอยู่ในโลกที่ไม่ใช่ความจริง หรือที่ที่อันตรายแค่ไหน พวกเขาก็ไม่สนแม้แต่น้อย)",
  ui_story_5024_50241601_43_dialog_content = "(ตราบใดที่เชื่อมั่นในศรัทธาของตน นั่นก็เพียงพอแล้วที่จะขับเคลื่อนให้ชีวิตดำเนินต่อไป...)",
  ui_story_5024_50241601_44_dialog_content = "หืมม? PlayerName คิดอะไรอยู่รึ?",
  ui_story_5024_50241601_45_dialog_content = "ถ้าเธอสนใจเกี่ยวกับทรู ออเดอร์ ฉันก็ยินดีอธิบายให้เธอฟังมากกว่านี้นะ",
  ui_story_5024_50241601_46_dialog_content = "เอ๊ะ...?",
  ui_story_5024_50241601_47_dialog_content = "คุณวิกตอเรียเรียนรู้พลังของเคเลสไทต์ตั้งแต่เมื่อไหร่กันน่ะ!",
  ui_story_5024_50241601_48_dialog_content = "หึหึ ฉันไม่มีพลังจิตอันยอดเยี่ยมของเธอหรอก...",
  ui_story_5024_50241601_49_dialog_content = "แต่อย่างไรก็ดี ตำราสีดำเล่มนี้ก็กระซิบคำพยากรณ์ที่ชัดเจนให้ฉันฟังหลายครั้งหลายครา",
  ui_story_5024_50241601_50_dialog_content = "\"เคเลสไทต์ผู้กังวลใจ กำลังหลงทางอยู่ในปริศนาแห่งสัจธรรม\"",
  ui_story_5024_50241601_51_dialog_content = "\"สุดท้ายก็เหลือเพียงแต่หัวสมองและท้องอันว่างเปล่า\"",
  ui_story_5024_50241601_52_dialog_content = "อะไรนะ!?",
  ui_story_5024_50241601_53_dialog_content = "อันนี้หมายความว่า...",
