  ui_story_5024_50241601_56_dialog_content = "หึหึ ในที่สุดงานฉลองที่ไร้กังวลก็เริ่มขึ้นได้แล้ว",
  ui_story_5024_50241601_57_dialog_content = "ไม่ทราบว่าแขกผู้ไม่ได้รับเชิญจะให้เกียรติร่วมงานของฉันจะได้ไหม?",
  ui_story_5024_50241601_58_dialog_content = "ยังไงซะ นี่ก็เป็นโอกาสอันหาได้ยากยิ่ง ที่จะได้ล่อลวงสมาชิกจากสวนลูโมโพลิส",
