  ui_story_5024_50241601_61_dialog_content = "ยัยผู้หญิงเพี้ยนนี่!!!",
  ui_story_5024_50241601_62_dialog_content = "<color=#e8d9bb>กิ๊ง กิ๊ง กิ๊ง...</color>",
