  ui_story_5024_50241601_68_dialog_content = "(พยายามทำทุกอย่างให้ตัวเองได้เข้าโรงละคร เพื่อที่จะออกมาอย่างปลอดภัย พิลึกสุด ๆ ไปเลย!)",
  ui_story_5024_50241601_69_dialog_content = "(เราพยายามช่วยเลนอร์ตามหาแม่ แต่สุดท้ายจิตสำนึกที่หลงเหลืออยู่ของแม่ก็ช่วยเราไว้ อืมม ฟังแล้วก็แปลกชอบกล!)",
