  ui_story_5024_50241601_84_dialog_content = "ฉันว่ามันอร่อยมากเลย!",
  ui_story_5024_50241601_85_dialog_content = "อ๊ะ? เอาเถอะ... รสนิยมการกินของพี่นี่ไม่เหมือนใครจริง ๆ...",
