  ui_story_5024_50241601_88_dialog_content = "เอ่อ...",
  ui_story_5024_50241601_89_dialog_content = "ร-เรื่องวุ่นวายแบบนั้น! แต่ในเมื่อพี่อุตส่าห์ขอดี ๆ ฉันก็...",
