  ui_story_5024_50241601_169_dialog_content = "\"ทารกหญิงวัยหัดคลานคนหนึ่งไม่เชื่อฟังแม่ของเธอ\"",
  ui_story_5024_50241601_170_dialog_content = "\"เด็กน้อยผู้ไร้เดียงสาปีนขึ้นไปบนเวที และถูกสาปให้กลายเป็นตุ๊กตา\"",
  ui_story_5024_50241601_171_dialog_content = "\"■■ช่างไร้ปรานี แต่ก็ไม่ได้ชิงวิญญาณของเธอไป\"",
  ui_story_5024_50241601_172_dialog_content = "[เส้นทาง]",
  ui_story_5024_50241601_173_dialog_content = "\"ในซอกหลืบที่อยู่เหนือกฎเกณฑ์ใด ๆ ปาฏิหาริย์ที่สูญสลายไปก่อนเวลาอันควร กำลังรอคอยวันที่จะกลับมา\"",
  ui_story_5024_50241601_174_dialog_content = "\"ผู้เป็นแม่รีบรุดมาอย่างรวดเร็ว เพื่อทวงคืนสิ่งที่เธอสูญเสียไป\"",
  ui_story_5024_50241601_175_dialog_content = "\"แม้ว่านั่นจะต้องแลกมาด้วยวิญญาณของเธอก็ตาม\"",
  ui_story_5024_50241601_176_dialog_content = "[บรรจบ]",
  ui_story_5024_50241601_177_dialog_content = "\"การแสดงครั้งใหม่ล้มเหลว แต่เรายังมีโอกาสต่อไป ละครจะไม่มีวันจบจนกว่ามันจะสำเร็จ\"",
  ui_story_5024_50241601_178_dialog_content = "\"ในโรงละครแห่งนั้น ยังมีหนึ่งศรัทธาที่ล่องลอยในความเงียบงัน\"",
  ui_story_5024_50241601_179_dialog_content = "\"มันแบกรับน้ำหนักของชีวิต และเฝ้ารอคอยเรื่อยมา\"",
  ui_story_5024_50241601_180_dialog_content = "\"รอวันได้พบเด็กหญิงผู้มีร่างกายเป็นตุ๊กตา ที่ออกตามหาแม่...\"",
  ui_story_5024_50241601_181_dialog_content = "แบบนี้นี่เอง... นี่คือคำพยากรณ์ของเด็กสาวตุ๊กตาและแม่ของเธอ",
  ui_story_5024_50241601_182_dialog_content = "เธอเดินทางมายังคฤหาสน์แห่งความจริงพร้อมกับ PlayerName...",
  ui_story_5024_50241601_183_dialog_content = "คุณทราบเรื่องนี้ล่วงหน้าแล้วอย่างนั้นเหรอครับ?",
  ui_story_5024_50241601_184_dialog_content = "ในสายตาของฉัน มันก็เป็นเพียงเรื่องราวที่สมเหตุสมผลเรื่องหนึ่งเท่านั้น",
  ui_story_5024_50241601_185_dialog_content = "ถนนสองสายที่มุ่งหน้าหากัน ย่อมต้องพบกันสักวันหนึ่งอยู่แล้ว",
  ui_story_5024_50241601_186_dialog_content = "และตัวฉันก็แค่ยืนอยู่ ณ จุดที่เส้นทางบรรจบกัน มองผู้เป็นแม่จูงลูกน้อยกลับสู่จุดเริ่มต้นทีละก้าว",
  ui_story_5024_50241601_187_dialog_content = "จบบริบูรณ์"
}
